 S('India','The Metropolitan Museum of Art. South Asia, 1600–1800; National Army Museum. Battle of Plassey.','https://www.metmuseum.org/toah/ht/09/ssa.html','https://www.nam.ac.uk/explore/battle-plassey');
 S('SEAsia','The Metropolitan Museum of Art. Southeast Asia, 1600–1800; National Library Board Singapore. Old Johor kingdom; A Battle Captured in a Map.','https://82nd-and-fifth.metmuseum.org/toah/ht/09/sse.html','https://www.nlb.gov.sg/main/article-detail?cmsuuid=36c71e6b-bfee-43ba-bc5c-086c15cd0df4','https://biblioasia.nlb.gov.sg/all-sections/vol-11-issue-4-jan-mar-2016-contrafactur-battle-dutch-portuguese-de-bry/');
 S('Siberia','Presidential Library. Город Енисейск; Yakutsk municipal historical chronology, 1632–1708; Library of Congress. Meeting of Frontiers.','https://www.prlib.ru/collections/2069315','https://yakutskcity.ru/yakutsk/history/istoriya-goroda-yakutska/s-1632-po-1708-gody/','https://www.loc.gov/collections/meeting-of-frontiers/articles-and-essays/');
 S('Russia','Treaty of Nystad, 1721, Electronic Library of Historical Documents; Saint Petersburg Institute of History. 300 лет Ништадтскому миру; Manifesto concerning Crimea, Taman and Kuban, 1783.','https://docs.historyrussia.org/ru/nodes/335720-nishtadtskiy-mirnyy-dogovor-mezhdu-rossiey-i-shvetsiey-30-avgusta-1721-g','https://spbiiran.ru/300-let-nishtadtskomu-miru/','https://constitutions.ru/?p=18821');
 S('Europe','Treaty of Westphalia, 1648, Yale Law School Avalon Project; Deutsches Historisches Museum. Preußen 1701; The Metropolitan Museum of Art. European historical chronologies.','https://avalon.law.yale.edu/17th_century/westphal.asp','https://www.dhm.de/publikation/preussen-1701-eine-europaeische-geschichte/','https://www.dhm.de/archiv/ausstellungen/staendige-ausstellung/gliederung.html','https://www.metmuseum.org/toah/ht/09/euwf.html');
 S('Britain','UK Parliament. The Articles, constitution and trade; Articles of Union, 1707.','https://www.parliament.uk/about/living-heritage/evolutionofparliament/legislativescrutiny/act-of-union-1707/overview/the-articles-constitution-and-trade/','https://www.parliament.uk/globalassets/documents/heritage/articlesofunion.pdf');
 S('France','Château de Versailles. Versailles at the Heart of the French Revolution; Serment du Jeu de paume.','https://en.chateauversailles.fr/discover/history/key-dates/versailles-heart-french-revolution','https://www.chateauversailles.fr/decouvrir/histoire/les-grandes-dates/serment-jeu-paume');
 const old=c.entries.filter(e=>e.region==='eurasia'&&e.phases.some(p=>p.from<=1600&&1600<p.to)).map(e=>e.id),done=[],fresh=[];
 const entry=id=>{const e=c.entries.find(e=>e.id===id);if(!e)throw Error(id);return e;};
 const G=id=>structuredClone(c.areas.filter(a=>a.entry===id&&a.from<=1600&&1600<a.to).sort((a,b)=>b.from-a.from)[0].polygons);
 const P=id=>entry(id).phases.find(p=>p.from<=1600&&1600<p.to);
 const src=s=>(Array.isArray(s)?s:[s]).map(x=>x.startsWith('to1789')?x:'to1789'+x);
 const rows=(id,s,color,rr,isNew,meta)=>{
  const fallback=isNew?meta.coord:(P(id).coord||entry(id).coord);
  const pp=rr.map(r=>H.phase(r[0],r[1],T(r[2]),T(r[3]),src(s),{coord:fallback,...(r[6]||{})}));
  if(isNew){H.entry(id,'eurasia',meta.kind||'state',meta.coord,T(meta.name),pp);fresh.push(id);}else{H.continueEntry(id,pp);done.push(id);}
  rr.forEach(r=>H.area(id,r[0],r[1],r[4]||G(id),{kind:r[5]||'polity',color,sources:src(s)}));
 };
 const M=(id,s,color,rr)=>rows(id,s,color,rr,false);
 const A=(id,name,coord,s,color,rr,kind='state')=>rows('1789-'+id,s,color,rr,true,{name,coord,kind});
 const E=(id,y,who,pt,title,text,s,kind='politics',extra={})=>H.event('1789-'+id,y,who,kind,pt,T(title),T(text),src(s),extra);
 const N=(id,from,topic,text)=>{const p=entry(id).phases.find(p=>p.from===from);(p.learning??={})[topic]=T(text);};

 // East Asia: separate dynastic claims from the places actually controlled.
 const china=G('late-ming'),manchuria=[[122,39.8],[124,39.8],[130,42.2],[131,45],[126,47],[121.5,45],[122,42]],hetuala=[[124.3,41.2],[126.6,41.2],[128,43.8],[125.5,45],[124.2,43]],southwestResistance=[[98,22.5],[100.3,22.5],[100.5,24.8],[98.4,25.6],[97.7,24]],northChina=[[107,34],[112,33.7],[117.5,34],[121,36.5],[119,40.5],[115,41.8],[108,40]],lowerYangtze=[[112,28.5],[118,28.5],[122,30],[121.5,33.5],[117,34],[112,33.5]],southChina=[[107,21.5],[113,21.6],[117.5,24],[120,27],[118,29],[112,29],[106,26]],yunnan=[[98,22],[103,22],[106,24],[106,27.6],[102,28],[98,26]],mongolEast=[[105,42],[112,41],[120,43],[121,46],[116,48],[110,48],[105,46]],khalkha=[[90,44],[97,43],[106,44],[114,46],[117,49],[108,51],[98,51],[90,49]],dzungaria=[[80,43],[86,42.5],[91,45],[89,48],[84,49],[79,47]],tarim=[[75.7,38.2],[79,36.5],[85,37],[89,39],[88,42],[83,42.5],[78,41.5],[75.5,40]],taiwanWest=[[120.02,22.4],[120.7,22.4],[120.9,24],[120.3,23.6]];
 M('late-ming','China','#bda277',[[1601,1644,'Последние десятилетия Мин|Final Ming decades|Миндин акыркы он жылдыктары','Налоговый кризис, восстания и война с маньчжурами подрывают двор. В 1644 году Пекин падает.|Fiscal crisis, rebellions and war with the Manchus undermine the court. Beijing falls in 1644.|Салык кризиси, көтөрүлүштөр жана манжулар менен согуш сарайды алсыратат. Пекин 1644-жылы алынат.',china,'polity',{coord:[116.4,39.9]}]]);
 A('jurchen','Поздняя Цзинь и ранняя Цин|Later Jin and early Qing|Соңку Цзинь жана алгачкы Цин',[124.97,41.72],'China','#97a695',[
 [1616,1621,'Хэту-Ала и Поздняя Цзинь|Hetu Ala and Later Jin|Хэту-Ала жана Соңку Цзинь','Нурхаци провозглашает государство в Хэту-Ала. Походы против Мин начинаются в 1618 году; Шэньян ещё не захвачен.|Nurhaci proclaims his state at Hetu Ala. Campaigns against the Ming begin in 1618; Shenyang has not yet fallen.|Нурхаци Хэту-Алада мамлекет жарыялайт. Минге каршы жортуулдар 1618-жылы башталат; Шэньян али алынган эмес.',hetuala,'influence'],
 [1621,1625,'Ляоян и завоевание Ляодуна|Liaoyang and the conquest of Liaodong|Ляоян жана Ляодунду каратуу','После взятия Шэньяна и Ляояна двор переносится в Ляоян. Мин сохраняет западные укрепления, включая Нинъюань.|After taking Shenyang and Liaoyang, the court moves to Liaoyang. The Ming retain western strongholds including Ningyuan.|Шэньян менен Ляоян алынгандан кийин сарай Ляоянга көчөт. Мин батыш чептерин, анын ичинде Нинъюанды сактайт.',manchuria,'influence',{coord:[123.17,41.27]}],
 [1625,1636,'Шэньян и знамённое государство|Shenyang and the banner state|Шэньян жана туу мамлекети','Двор перемещается в Шэньян. Поход на минский Нинъюань в 1626 году заканчивается неудачей.|The court moves to Shenyang. The 1626 attack on Ming-held Ningyuan fails.|Сарай Шэньянга көчөт. Мин кармаган Нинъюанга 1626-жылдагы кол салуу ийгиликсиз аяктайт.',manchuria,'influence',{coord:[123.43,41.8]}],
 [1636,1644,'Провозглашение Цин|Proclamation of the Qing|Циндин жарыяланышы','Хунтайцзи принимает новое династическое имя. Двор соединяет маньчжурские, монгольские и китайские войска.|Hong Taiji adopts the new dynastic name. The court combines Manchu, Mongol and Chinese forces.|Хунтайцзи жаңы династиялык ат алат. Сарай манжу, монгол жана кытай аскерлерин бириктирет.',[manchuria,mongolEast],'influence',{coord:[123.43,41.8]}]
 ]);
 A('qing','Империя Цин|Qing empire|Цин империясы',[116.4,39.9],['China','Frontier'],'#96a185',[
 [1644,1645,'Цин в Пекине|Qing in Beijing|Пекиндеги Цин','Цинский двор занимает Пекин; минские дворы и другие противники продолжают борьбу на юге.|The Qing court takes Beijing; Ming courts and other opponents continue resistance in the south.|Цин сарайы Пекинди алат; Мин сарайлары жана башка каршылаштар түштүктө күрөшөт.',[manchuria,mongolEast,northChina]],
 [1645,1650,'Продвижение к Янцзы|Advance to the Yangtze|Янцзыга жылуу','После падения Нанкина Цин закрепляется в нижнем течении Янцзы. Южное сопротивление продолжается.|After Nanjing falls, Qing rule expands along the lower Yangtze. Southern resistance continues.|Нанкин алынгандан кийин Цин бийлиги төмөнкү Янцзыда жайылат. Түштүктө каршылык уланат.',[manchuria,mongolEast,northChina,lowerYangtze]],
 [1650,1659,'Южные завоевания|Southern conquests|Түштүктөгү каратуулар','Цинские армии расширяют владения на юге; двор Юнли отступает к юго-западной границе.|Qing armies extend southern domains; the Yongli court retreats toward the southwestern frontier.|Цин аскерлери түштүк ээликтерин кеңейтет; Юнли сарайы түштүк-батыш чекке чегинет.',[manchuria,mongolEast,northChina,lowerYangtze,southChina]],
 [1659,1662,'Завоевание Юньнани|Conquest of Yunnan|Юньнанды каратуу','Цинские войска берут Куньмин. Минские силы продолжают сопротивление у юго-западной границы, а двор Юнли уходит в Бирму.|Qing troops take Kunming. Ming forces continue resistance near the southwestern frontier while Yongli’s court flees to Burma.|Цин аскерлери Куньминди алат. Мин күчтөрү түштүк-батыш чек арада каршылыкты улантып, Юнли сарайы Бирмага кетет.',[manchuria,mongolEast,...china]],
 [1662,1691,'Закрепление власти в Китае|Consolidating rule in China|Кытайдагы бийликтин бекемделиши','После гибели Юнли крупное сопротивление продолжается в отдельных областях; восстание трёх князей подавлено в 1681 году.|After Yongli’s death, major resistance persists in some regions; the Three Feudatories revolt is suppressed in 1681.|Юнли өлгөндөн кийин айрым аймактарда ири каршылык уланат; үч княздын көтөрүлүшү 1681-жылы басылат.',[manchuria,mongolEast,...china]],
 [1691,1755,'Халха и цинская система управления|Khalkha and Qing administration|Халха жана Цин башкаруусу','Халхаские князья признают цинского императора. Знамённое управление сохраняет монгольскую знать.|Khalkha princes acknowledge the Qing emperor. Banner administration retains Mongol nobles.|Халха княздары Цин императорун тааныйт. Туу башкаруусу монгол ак сөөктөрүн сактайт.',[manchuria,mongolEast,...china,khalkha]],
 [1755,1759,'Война в Джунгарии|War in Dzungaria|Жуңгариядагы согуш','Цинские армии берут Или. Восстания, массовое насилие, эпидемии и бегство населения разрушают Джунгарское ханство.|Qing armies take Ili. Rebellions, mass violence, epidemics and flight devastate the Dzungar Khanate.|Цин аскерлери Илени алат. Көтөрүлүштөр, массалык зомбулук, эпидемиялар жана калктын качышы Жуңгар хандыгын кыйратат.',[manchuria,mongolEast,...china,khalkha,dzungaria],'influence'],
 [1759,1790,'Или и оазисы Тарима под Цин|Ili and the Tarim oases under Qing rule|Цин бийлигиндеги Иле жана Тарим оазистери','После разгрома ходжей Цин подчиняет оазисы Тарима. Военные гарнизоны сосуществуют с местными беками; кыргызские и казахские общины западнее сохраняют собственную власть.|After defeating the khojas, the Qing subjugate the Tarim oases. Garrisons coexist with local begs; Kyrgyz and Kazakh communities farther west retain their own authority.|Кожолор жеңилгенден кийин Цин Тарим оазистерин баш ийдирет. Аскер гарнизондору жергиликтүү бектер менен катар иштейт; батыштагы кыргыз жана казак жамааттары өз бийлигин сактайт.',[manchuria,mongolEast,...china,khalkha,dzungaria,tarim]]
 ]);
 A('southern-ming','Южные Мин|Southern Ming|Түштүк Мин',[118.8,32.06],'China','#bda277',[[1644,1645,'Минский двор в Нанкине|Ming court in Nanjing|Нанкиндеги Мин сарайы','Минские принцы восстанавливают двор после потери Пекина.|Ming princes re-establish a court after losing Beijing.|Мин ханзадалары Пекинди жоготкондон кийин сарайды калыбына келтирет.',[lowerYangtze,southChina,yunnan],'influence'],[1645,1650,'Южные дворы и сопротивление|Southern courts and resistance|Түштүк сарайлар жана каршылык','После потери Нанкина соперничающие минские дворы продолжают войну.|After Nanjing falls, rival Ming courts continue the war.|Нанкин алынгандан кийин атаандаш Мин сарайлары согушту улантат.',[southChina,yunnan],'influence',{coord:[112.46,23.05]}],[1650,1659,'Юнли и юго-запад|Yongli and the southwest|Юнли жана түштүк-батыш','Двор Юнли опирается на юго-западные силы и затем уходит в Бирму. Его гибель в 1662 году завершает эту линию императорского сопротивления.|Yongli relies on southwestern forces and then retreats into Burma. His death in 1662 ends this line of imperial resistance.|Юнли түштүк-батыш күчтөргө таянып, кийин Бирмага кетет. Анын 1662-жылдагы өлүмү императордук каршылыктын бул бутагын аяктатат.',yunnan,'influence',{coord:[102.71,25.04]}],[1659,1662,'Приграничное сопротивление Мин|Ming frontier resistance|Миндин чек ара каршылыгы','После потери Куньмина силы Ли Динго продолжают борьбу у бирманской границы. Императорский двор находится в изгнании; прежняя Юньнань уже не под его властью.|After losing Kunming, Li Dingguo’s forces continue fighting near the Burmese frontier. The imperial court is in exile and no longer controls former Yunnan domains.|Куньминди жоготкондон кийин Ли Динго күчтөрү Бирма чек арасында күрөшөт. Императордук сарай сүргүндө болуп, мурдагы Юньнань ээликтерин башкарбайт.',southwestResistance,'influence',{coord:[99,24]}]]);
 A('taiwan-dutch','Тайвань · нидерландские укрепления|Taiwan · Dutch strongholds|Тайвань · нидерланд чептери',[120.16,23],'Taiwan','#9ba8af',[[1624,1662,'Зеландия и юго-западное побережье|Zeelandia and the southwest coast|Зеландия жана түштүк-батыш жээк','Ост-Индская компания строит торговую базу у Тайнаня. Внутренние горные общины сохраняют самостоятельность.|The East India Company establishes a trading base near Tainan. Interior mountain communities retain autonomy.|Ост-Индия компаниясы Тайнанга жакын соода базасын түзөт. Ички тоолуу жамааттар өз алдынчалыгын сактайт.',taiwanWest,'settlement']],'region');
 A('taiwan-zheng','Тайвань · власть Чжэн|Taiwan · Zheng rule|Тайвань · Чжэн бийлиги',[120.2,23],'Taiwan','#b4a17a',[[1662,1683,'Чжэн Чэнгун и его наследники|Zheng Chenggong and his successors|Чжэн Чэнгун жана анын мураскерлери','Чжэн Чэнгун вытесняет нидерландцев. Его наследники поддерживают морскую торговлю и сопротивление Цин.|Zheng Chenggong expels the Dutch. His successors maintain maritime trade and resistance to the Qing.|Чжэн Чэнгун нидерланддарды сүрүп чыгарат. Анын мураскерлери деңиз соодасын жана Цинге каршылыкты улантат.',taiwanWest]]);
 A('taiwan-qing','Тайвань · цинское управление|Taiwan · Qing administration|Тайвань · Цин башкаруусу',[120.2,23],'Taiwan','#96a185',[[1683,1790,'Западные равнины под Цин|Western plains under Qing rule|Цин бийлигиндеги батыш түздүктөр','После капитуляции Чжэн Цин вводит управление западными равнинами. Горные общества не превращаются автоматически в подконтрольные уезды.|After the Zheng surrender, the Qing administer the western plains. Mountain societies do not automatically become governed counties.|Чжэн багынгандан кийин Цин батыш түздүктөрдү башкарат. Тоолуу коомдор дароо башкарылуучу уезддерге айланбайт.',taiwanWest,'influence']],'region');
 M('late-mongol',['Central','China'],'#aaa185',[[1601,1636,'Монгольские князья и маньчжурское усиление|Mongol princes and the Manchu rise|Монгол княздары жана манжулардын күчөшү','Разные монгольские объединения заключают союзы и ведут войны с маньчжурским двором.|Different Mongol groupings form alliances and wage war with the Manchu court.|Ар башка монгол бирикмелери Манжу сарайы менен союз түзүп, согушат.',G('late-mongol'),'influence'],[1636,1691,'Халхаские ханства|Khalkha khanates|Халха хандыктары','Халхаские ханы сохраняют отдельную власть севернее цинских зависимых княжеств. Джунгарское наступление ведёт к обращению за защитой Цин.|Khalkha khans retain separate authority north of Qing-dependent principalities. Dzungar advances lead them to seek Qing protection.|Халха хандары Цинге көз каранды княздыктардын түндүгүндө өз бийлигин сактайт. Жуңгар чабуулу Цинден коргоо издөөгө алып келет.',khalkha,'influence',{coord:[102.82,47.2]}]]);
 M('japan','Japan','#a7a09a',[[1601,1603,'Иэясу после Сэкигахары|Ieyasu after Sekigahara|Сэкигахарадан кийинки Иэясу','Токугава укрепляет союзников и перераспределяет владения даймё.|Tokugawa strengthens allies and redistributes daimyo domains.|Токугава союздаштарын бекемдеп, даймё ээликтерин кайра бөлөт.'],[1603,1635,'Сёгунат Токугава|Tokugawa shogunate|Токугава сёгунаты','Иэясу получает титул сёгуна. Эдо становится центром военного правительства; императорский двор остаётся в Киото.|Ieyasu becomes shogun. Edo becomes the military government’s centre; the imperial court remains in Kyoto.|Иэясу сёгун болот. Эдо аскердик өкмөттүн борборуна айланат; император сарайы Киотодо калат.',null,'polity',{coord:[139.75,35.68]}],[1635,1790,'Эдо: владения, города и контролируемая торговля|Edo: domains, cities and regulated trade|Эдо: ээликтер, шаарлар жана жөнгө салынган соода','Сёгунат и княжества совместно управляют страной. Растут города, печатная культура и обмен через разрешённые порты.|Shogunate and domains share government. Cities, print culture and exchange through authorised ports grow.|Сёгунат менен княздыктар өлкөнү бирге башкарат. Шаарлар, басма маданияты жана уруксаттуу порттор аркылуу соода өсөт.',null,'polity',{coord:[139.75,35.68]}]]);
 M('late-joseon','Korea','#97a1b1',[[1601,1637,'Восстановление Чосона и маньчжурские вторжения|Joseon recovery and Manchu invasions|Чосондун калыбына келиши жана манжу басып кирүүлөрү','Чосон восстанавливается после японских войн; маньчжурские походы 1627 и 1636 годов меняют его внешние связи.|Joseon recovers from the Japanese wars; Manchu campaigns in 1627 and 1636 reshape foreign relations.|Чосон жапон согуштарынан калыбына келет; 1627 жана 1636-жылдардагы манжу жортуулдары тышкы байланыштарды өзгөртөт.'],[1637,1790,'Чосон в отношениях с Цин|Joseon’s relations with the Qing|Чосондун Цин менен мамилелери','Корейский двор признаёт верховенство Цин, сохраняя династию и собственное управление. Развиваются земледелие, ремесло и книжная культура.|The Korean court acknowledges Qing suzerainty while retaining its dynasty and government. Farming, crafts and book culture develop.|Корея сарайы династиясын жана өз башкаруусун сактап, Цин үстөмдүгүн тааныйт. Дыйканчылык, кол өнөрчүлүк жана китеп маданияты өнүгөт.']]);

 // Inner Asia: khanates, oasis governments and pastoral communities are distinct layers.
 S('Khiva','Yuri Bregel. Khiva; Anke von Kügelgen. Manghits, Encyclopaedia Iranica.','https://www.iranicaonline.org/articles/khiva/','https://www.iranicaonline.org/articles/manghits/');
 c.sources.to1789Taiwan.urls.push('https://www.nmth.gov.tw/en/News_Content_Due.aspx?n=4315&s=207564','https://www.nmth.gov.tw/News_Publish_Content.aspx?n=4164&s=139520');
 c.sources.to1789Taiwan.title+=' National Museum of Taiwan History. Transcending 1624; 國姓爺與荷蘭人戰爭.';
 const buk=G('early-bukhara'),khiva=G('early-khwarazm'),tianshan=G('late-kyrgyz-tianshan'),yenisei=G('late-kyrgyz'),kazakh=G('early-kazakh'),westSteppe=[[50,45],[57,43],[65,44],[70,47],[67,51],[59,52],[52,49]],fergana=[[70.2,39.8],[72.4,39.9],[73.1,40.7],[72.2,41.4],[70.3,41.2]];
 A('dzungar','Джунгарское ханство|Dzungar Khanate|Жуңгар хандыгы',[81.3,43.9],['Central','Frontier'],'#a79391',[[1635,1680,'Ойратская держава в Джунгарии|Oirat state in Dzungaria|Жуңгариядагы ойрот мамлекети','Ойратские правители объединяют кочевые силы, используют монастыри, торговлю и огнестрельное оружие.|Oirat rulers consolidate pastoral forces and draw on monasteries, trade and firearms.|Ойрот башкаруучулары көчмөн күчтөрдү бириктирип, монастырларды, сооданы жана ок атуучу куралдарды пайдаланат.',dzungaria,'influence'],[1680,1755,'Джунгария и зависимые оазисы|Dzungaria and dependent oases|Жуңгария жана көз каранды оазистер','Джунгарские ханы подчиняют Таримские оазисы. Войны с Цин, казахами и кыргызами меняют пограничные зоны.|Dzungar khans subordinate the Tarim oases. Wars with the Qing, Kazakhs and Kyrgyz reshape frontier zones.|Жуңгар хандары Тарим оазистерин баш ийдирет. Цин, казактар жана кыргыздар менен согуштар чек аймактарды өзгөртөт.',[dzungaria,tarim],'influence'],[1755,1758,'Сопротивление цинскому завоеванию|Resistance to Qing conquest|Цин каратуусуна каршылык','После пленения Даваци Амурсана продолжает борьбу. Походы Цин и гибель населения разрушают ханство.|After Dawachi is captured, Amursana continues resistance. Qing campaigns and population losses destroy the khanate.|Даваци туткунга алынгандан кийин Амурсана күрөштү улантат. Цин жортуулдары жана калктын кырылышы хандыкты кыйратат.',dzungaria,'influence']]);
 M('early-yarkand','Central','#bd9c78',[[1601,1680,'Яркендские ханы и оазисы|Yarkand khans and oasis towns|Яркенд хандары жана оазис шаарлары','Чагатаидские ханы правят через оазисные элиты; растёт политическая роль ходжей.|Chagataid khans govern through oasis elites; the khojas gain political influence.|Чагатай тукумунун хандары оазис төбөлдөрү аркылуу башкарат; кожолордун саясий ролу өсөт.'],[1680,1705,'Яркенд под джунгарским верховенством|Yarkand under Dzungar suzerainty|Жуңгар үстөмдүгүндөгү Яркенд','Джунгарское вмешательство ограничивает власть ханов. Ходжи и местные беки продолжают борьбу за оазисы.|Dzungar intervention restricts khanly power. Khojas and local begs continue competing over the oases.|Жуңгар кийлигишүүсү хандардын бийлигин чектейт. Кожолор менен жергиликтүү бектер оазистер үчүн күрөшөт.',null,'influence']]);
 M('early-turfan','Central','#ac9d84',[[1601,1680,'Турфанский оазис|Turfan oasis|Турпан оазиси','Местные правители связывают оазисное земледелие с караванной торговлей и соперничеством могульских дворов.|Local rulers connect irrigated farming with caravan trade and rivalry among Moghul courts.|Жергиликтүү башкаруучулар сугат дыйканчылыгын кербен соодасы жана могол сарайларынын атаандаштыгы менен байланыштырат.'],[1680,1759,'Турфан между Джунгарией и Цин|Turfan between Dzungaria and the Qing|Жуңгария менен Циндин ортосундагы Турпан','Местные элиты маневрируют между джунгарскими ханами и Цин. Оазис сохраняет собственное население и хозяйство.|Local elites manoeuvre between Dzungar khans and the Qing. The oasis retains its population and economy.|Жергиликтүү төбөлдөр жуңгар хандары менен Циндин ортосунда саясат жүргүзөт. Оазис калкын жана чарбасын сактайт.',null,'influence']]);
 A('altishahr','Таримские оазисы и ходжи|Tarim oases and khojas|Тарим оазистери жана кожолор',[76,39.45],['Central','Frontier'],'#baaa86',[[1705,1755,'Оазисы под джунгарским верховенством|Oases under Dzungar suzerainty|Жуңгар үстөмдүгүндөгү оазистер','Беки и религиозные роды управляют оседлыми общинами при джунгарских поборах.|Begs and religious lineages administer settled communities under Dzungar exactions.|Бектер жана диний тукумдар жуңгар салыктарына баш ийген отурукташкан жамааттарды башкарат.',tarim,'influence'],[1755,1759,'Война ходжей и наступление Цин|Khoja war and Qing advance|Кожолордун согушу жана Циндин чабуулу','После падения джунгарской власти братья-ходжи борются с Цин. В 1759 году цинские войска завершают завоевание оазисов.|After Dzungar power collapses, the khoja brothers fight the Qing. Qing forces complete the conquest of the oases in 1759.|Жуңгар бийлиги кулагандан кийин ага-ини кожолор Цин менен согушат. Цин аскерлери оазистерди каратууну 1759-жылы бүтүрөт.',tarim,'influence']],'region');
 M('early-kazakh','Central','#b3a075',[[1601,1723,'Казахские ханы и степные объединения|Kazakh khans and steppe groupings|Казак хандары жана талаа бирикмелери','Ханы, султаны и бии управляют перекрывающимися союзами. Пастбища связаны с городами Сырдарьи.|Khans, sultans and biys govern overlapping alliances. Pastures are linked to Syr Darya towns.|Хандар, султандар жана бийлер өз ара байланышкан бирикмелерди башкарат. Жайыттар Сыр-Дарыя шаарлары менен байланышат.',kazakh,'influence'],[1723,1758,'Джунгарские войны и перемещения|Dzungar wars and displacement|Жуңгар согуштары жана жер которуулар','Вторжения вызывают потери и перемещения. Часть ханов ищет российское покровительство; это не единое присоединение всех степей.|Invasions cause losses and displacement. Some khans seek Russian protection; this does not annex all the steppe at once.|Баскынчылыктар жоготууларды жана жер которууну жаратат. Айрым хандар Орусиянын колдоосун издейт; бул бүт талаанын бир учурда кошулушу эмес.',westSteppe,'influence',{coord:[62,47]}],[1758,1790,'Казахские объединения после Джунгарии|Kazakh groupings after Dzungaria|Жуңгариядан кийинки казак бирикмелери','Казахские силы возвращаются к восточным пастбищам. Ханы ведут отношения с Россией и Цин, сохраняя местную власть.|Kazakh groups return to eastern pastures. Khans maintain relations with Russia and the Qing while retaining local authority.|Казак топтору чыгыш жайыттарына кайтып келет. Хандар жергиликтүү бийлигин сактап, Орусия жана Цин менен мамиле жүргүзөт.',kazakh,'influence']]);
 M('late-kyrgyz',['Kyrgyz','Central'],'#a9b29c',[[1601,1703,'Енисейские кыргызские княжества|Yenisei Kyrgyz principalities|Енисей кыргыз княздыктары','Князья и общины участвуют в соперничестве России и Джунгарии. Сбор дани не означает исчезновения местного управления.|Princes and communities face Russian–Dzungar rivalry. Tribute collection does not erase local government.|Княздар менен жамааттар Орусия жана Жуңгариянын атаандаштыгына туш болот. Алым чогултуу жергиликтүү башкарууну жок кылбайт.',yenisei,'influence']]);
 A('yenisei-communities','Общины Среднего Енисея|Middle Yenisei communities|Орто Енисей жамааттары',[90.9,53.7],['Kyrgyz','Siberia'],'#a9b29c',[[1703,1790,'Переселение и оставшееся население|Deportation and remaining population|Көчүрүү жана калган калк','В 1703 году джунгары переселяют значительную часть енисейских кыргызов. Оставшиеся местные общины продолжают жить в бассейне Енисея.|In 1703 the Dzungars deport a substantial part of the Yenisei Kyrgyz. Remaining local communities continue living in the Yenisei basin.|1703-жылы жуңгарлар енисей кыргыздарынын олуттуу бөлүгүн көчүрөт. Калган жергиликтүү жамааттар Енисей алабында жашоосун улантат.',yenisei,'cultural']],'community');
 M('late-kyrgyz-tianshan',['Central','Frontier'],'#a9b29c',[[1601,1758,'Тянь-шаньские кыргызские объединения|Tian Shan Kyrgyz groupings|Теңир-Тоо кыргыз бирикмелери','Родовые объединения используют горные пастбища и оазисные связи. Джунгарские войны вызывают перемещения и меняют союзы.|Kin groupings use mountain pastures and oasis connections. Dzungar wars cause displacement and reshape alliances.|Уруу бирикмелери тоо жайыттарын жана оазис байланыштарын пайдаланат. Жуңгар согуштары жер которууларга жана союздардын өзгөрүшүнө алып келет.',tianshan,'cultural'],[1758,1790,'Кыргызские земли и цинская дипломатия|Kyrgyz lands and Qing diplomacy|Кыргыз жерлери жана Цин дипломатиясы','Китайские документы называют кыргызов «бурут». Посольства и пограничные отношения с Цин сосуществуют с властью местных биев.|Chinese records call the Kyrgyz Burut. Embassies and frontier relations with the Qing coexist with the authority of local biys.|Кытай документтери кыргыздарды «бурут» деп атайт. Цин менен элчилик жана чек аралык мамилелер жергиликтүү бийлердин бийлиги менен катар жашайт.',tianshan,'cultural']]);
 M('early-bukhara',['Central','Khiva'],'#b19a76',[[1601,1747,'Аштарханиды в Бухаре|Ashtarkhanids in Bukhara|Бухарадагы Аштарханиддер','Ханы правят при участии узбекских эмиров и городских элит. В 1740 году Надир-шах навязывает верховенство.|Khans govern with Uzbek emirs and urban elites. Nader Shah imposes suzerainty in 1740.|Хандар өзбек эмирлери жана шаар төбөлдөрү менен башкарат. 1740-жылы Надир-шах үстөмдүгүн таңуулайт.',buk],[1747,1785,'Возвышение мангытских правителей|Rise of Manghit rulers|Мангыт башкаруучуларынын көтөрүлүшү','Мангытские аталыки сосредоточивают власть; Мухаммад Рахим принимает ханский титул в 1756 году.|Manghit ataliqs concentrate power; Muhammad Rahim assumes the khanly title in 1756.|Мангыт аталыктары бийликти топтойт; Мухаммад Рахим 1756-жылы хан наамын алат.',buk],[1785,1790,'Эмир Шахмурад|Emir Shah Murad|Эмир Шахмурад','Шахмурад укрепляет власть эмира, опираясь на религиозный авторитет, налоги и городское хозяйство.|Shah Murad strengthens emiral rule through religious authority, taxation and the urban economy.|Шахмурад диний кадыр-баркка, салыкка жана шаар чарбасына таянып эмир бийлигин бекемдейт.',buk]]);
 M('early-khwarazm',['Khiva','Central'],'#ad9b82',[[1601,1740,'Хорезм и хивинские ханы|Khorezm and the khans of Khiva|Хорезм жана Хива хандары','Хивинский двор соединяет оазисное земледелие с узбекскими и туркменскими объединениями.|The Khivan court connects oasis agriculture with Uzbek and Turkmen groupings.|Хива сарайы оазис дыйканчылыгын өзбек жана түркмөн бирикмелери менен байланыштырат.',khiva],[1740,1747,'Поход Надир-шаха и зависимость|Nader Shah’s campaign and dependency|Надир-шахтын жортуулу жана көз карандылык','Надир-шах завоёвывает Хиву и вмешивается в назначение правителя. Местное общество и оазисное хозяйство сохраняются.|Nader Shah conquers Khiva and intervenes in appointing its ruler. Local society and oasis agriculture persist.|Надир-шах Хиваны каратып, башкаруучуну дайындоого кийлигишет. Жергиликтүү коом жана оазис чарбасы сакталат.',khiva,'influence'],[1747,1790,'Хива после афшаридского верховенства|Khiva after Afsharid suzerainty|Афшар үстөмдүгүнөн кийинки Хива','Соперничающие правители и племенные вожди борются за оазис. Во второй половине XVIII века усиливаются кунграты.|Rival rulers and tribal leaders compete over the oasis. Qongrats gain power in the later eighteenth century.|Атаандаш башкаруучулар жана уруу башчылары оазис үчүн күрөшөт. XVIII кылымдын экинчи жарымында коңураттар күчөйт.',khiva,'influence']]);
 A('kokand','Кокандское владение|Kokand polity|Кокон ээлиги',[70.94,40.53],'Central','#b5a385',[[1709,1790,'Мингские правители Ферганы|Ming rulers of Fergana|Фергананын миң башкаруучулары','Местная династия укрепляет власть в Фергане. Раннее Кокандское владение ещё не охватывает все позднейшие ханские территории.|A local dynasty consolidates power in Fergana. Early Kokand does not yet cover all the later khanate’s territories.|Жергиликтүү династия Ферганада бийлигин бекемдейт. Алгачкы Кокон ээлиги кийинки хандыктын бардык жерлерин камтыбайт.',fergana,'influence']]);
