 M('early-russia',['Russia','Andrusovo'],'#96a6b8',[
 [1601,1613,'Смута|Time of Troubles|Дүрбөлөң мезгили','Династический кризис, голод, гражданская война и иностранное вмешательство разрушают управление.|Dynastic crisis, famine, civil war and foreign intervention disrupt government.|Династиялык кризис, ачарчылык, жарандык согуш жана тышкы кийлигишүү башкарууну бузат.',rus],
 [1613,1617,'Начало правления Романовых|Beginning of Romanov rule|Романовдор бийлигинин башталышы','Новая династия восстанавливает управление после Смуты; война со Швецией продолжается.|The new dynasty restores government after the Time of Troubles; war with Sweden continues.|Жаңы династия Дүрбөлөңдөн кийин башкарууну калыбына келтирет; Швеция менен согуш уланат.',rus],
 [1617,1667,'Романовы после Столбовского мира|Romanovs after the Treaty of Stolbovo|Столбово тынчтыгынан кийинки Романовдор','Ингрия переходит Швеции. Государство восстанавливает внутреннее управление и позднее воюет с Речью Посполитой.|Ingria passes to Sweden. The state restores internal government and later fights the Commonwealth.|Ингрия Швецияга өтөт. Мамлекет ички башкарууну калыбына келтирип, кийин Речь Посполитая менен согушат.',rusInland],
 [1667,1703,'Андрусовское перемирие|Truce of Andrusovo|Андрусово жарашуусу','Перемирие признаёт российский контроль над Смоленском и Левобережьем Днепра. Ингрия остаётся шведской.|The truce recognises Russian control of Smolensk and the Dnieper’s left bank. Ingria remains Swedish.|Жарашуу Смоленск менен Днепрдин сол жээгиндеги орус көзөмөлүн тааныйт. Ингрия Швецияда калат.',[...rusInland,smolensk,leftBank]],
 [1703,1710,'Основание Петербурга|Foundation of Saint Petersburg|Петербургдун негизделиши','После занятия устья Невы Пётр основывает Петербург. Северная война продолжается.|After taking the Neva estuary, Peter establishes Saint Petersburg. The Great Northern War continues.|Нева куймасы алынгандан кийин Пётр Петербургду негиздейт. Түндүк согуш уланат.',[...rusInland,smolensk,leftBank,petersburg]],
 [1710,1721,'Занятие балтийских городов|Occupation of Baltic towns|Балтика шаарларынын алынышы','Российские войска занимают Ригу, Ревель и Выборг. Договорное признание приобретений последует в 1721 году.|Russian forces occupy Riga, Reval and Vyborg. Treaty recognition follows in 1721.|Орус аскерлери Рига, Ревель жана Выборгду алат. Ээликтер 1721-жылы келишим менен таанылат.',[...rusInland,smolensk,leftBank,petersburg,baltic,viborg]]
 ]);
 A('russian-empire','Российская империя|Russian Empire|Орусия империясы',[30.31,59.94],['Russia','Andrusovo'],'#96a6b8',[[1721,1743,'Балтийская империя|Baltic empire|Балтика империясы','Ништадтский мир закрепляет приобретения на Балтике. Петербург становится имперской столицей; крепостная зависимость сохраняется.|The Treaty of Nystad confirms Baltic acquisitions. Saint Petersburg is the imperial capital; serfdom persists.|Ништадт келишими Балтикадагы ээликтерди бекитет. Петербург империялык борбор болот; крепостной көз карандылык сакталат.',[...rus,smolensk,leftBank,baltic,viborg]],[1743,1774,'Абоский мир и юго-восточная Финляндия|Treaty of Åbo and southeastern Finland|Або келишими жана түштүк-чыгыш Финляндия','После войны со Швецией Россия получает Хамину, Лаппеэнранту и Савонлинну. Остальная Финляндия остаётся шведской.|After war with Sweden, Russia receives Hamina, Lappeenranta and Savonlinna. The rest of Finland remains Swedish.|Швеция менен согуштан кийин Орусия Хамина, Лаппеэнранта жана Савонлиннаны алат. Калган Финляндия Швецияда калат.',[...rus,smolensk,leftBank,baltic,viborg,abo1743]],[1774,1783,'Выходы к Чёрному морю|Access to the Black Sea|Кара деңизге чыгуу','Кючук-Кайнарджийский мир закрепляет российские позиции у Азова и Керчи. Крым формально остаётся отдельным ханством.|Küçük Kaynarca confirms Russian positions near Azov and Kerch. Crimea formally remains a separate khanate.|Күчүк-Кайнаржа келишими Азов жана Керч жанындагы орус позицияларын бекитет. Крым расмий өзүнчө хандык бойдон калат.',[...rus,smolensk,leftBank,baltic,viborg,abo1743,azov,[[36.35,45.2],[36.7,45.2],[36.7,45.5],[36.35,45.5]]]],[1783,1790,'Присоединение Крыма|Annexation of Crimea|Крымдын кошулушу','Российская власть присоединяет Крым в 1783 году. Местное татарское население продолжает жить в регионе при новом управлении.|Russia annexes Crimea in 1783. The local Tatar population continues living in the region under a new administration.|Орусия бийлиги 1783-жылы Крымды кошот. Жергиликтүү татар калкы жаңы башкаруу алдында аймакта жашоосун улантат.',[...rus,smolensk,leftBank,baltic,viborg,abo1743,azov,...crimea]]]);
 M('early-crimea',['Ottoman','Russia'],'#bc815a',[[1601,1774,'Гиреи и османское верховенство|Giray khans and Ottoman suzerainty|Гирей хандары жана Осмон үстөмдүгү','Крымские ханы сохраняют династию и собственные войска; их внешняя политика связана с Османской державой.|Crimean khans retain their dynasty and armies; their foreign policy is linked to the Ottoman state.|Крым хандары династиясын жана өз аскерин сактайт; тышкы саясаты Осмон мамлекети менен байланыштуу.',crimea],[1774,1783,'Независимость по договору и российское давление|Treaty independence and Russian pressure|Келишимдеги эгемендик жана Орусиянын басымы','Ханство освобождено от османского политического верховенства, но российское вмешательство ограничивает его самостоятельность.|The khanate is released from Ottoman political suzerainty, but Russian intervention limits its autonomy.|Хандык Осмон саясий үстөмдүгүнөн бошотулат, бирок Орусиянын кийлигишүүсү анын өз алдынчалыгын чектейт.',crimea,'influence']]);
 M('early-nogai','Steppe','#b3ab8f',[[1601,1634,'Ногайские степные союзы|Nogai steppe alliances|Ногой талаа союздары','Мирзы соперничают и заключают союзы с соседними державами. Калмыцкое продвижение усиливает давление с востока.|Mirzas compete and ally with neighbouring powers. Kalmyk advances increase pressure from the east.|Мырзалар атаандашып, коңшу державалар менен союз түзөт. Калмактардын жылышы чыгыштан басымды күчөтөт.',null,'influence'],[1634,1790,'Ногайские общины Северного Кавказа|Nogai communities of the North Caucasus|Түндүк Кавказдын ногой жамааттары','Часть ногайских объединений перемещается к Кубани и соседним степям. Кочевое хозяйство и местные союзы продолжаются.|Some Nogai groupings move toward the Kuban and adjoining steppes. Pastoral livelihoods and local alliances continue.|Ногой бирикмелеринин бир бөлүгү Кубанга жана коңшу талааларга көчөт. Көчмөн чарба жана жергиликтүү союздар уланат.',kuban,'cultural',{coord:[41,45]}]]);
