 M('early-mughal',['India','Deccan'],'#a6a47d',[[1601,1636,'Могольский двор и провинции|Mughal court and provinces|Могол сарайы жана провинциялар','Джахангир и Шах-Джахан наследуют систему Акбара. Налоги, армейские чины и провинциальные элиты связывают обширную державу.|Jahangir and Shah Jahan inherit Akbar’s system. Taxes, military ranks and provincial elites connect the empire.|Жахангир менен Шах-Жахан Акбардын тутумун мурастайт. Салыктар, аскердик даражалар жана провинция төбөлдөрү державаны байланыштырат.',mughal],[1636,1686,'Усиление в Декане|Expansion in the Deccan|Декандагы кеңейүү','После разгрома Низам-шахов Моголы закрепляются в северном Декане. Южные султанаты и маратхи продолжают борьбу.|After defeating the Nizam Shahis the Mughals consolidate the northern Deccan. Southern sultanates and the Marathas continue resisting.|Низам-шахтар жеңилгенден кийин Моголдор түндүк Деканда бекемделет. Түштүк султанаттары жана маратхалар каршылыгын улантат.',[...mughal,...ahmad]],[1686,1687,'Падение Биджапура|Fall of Bijapur|Бижапурдун кулашы','Аурангзеб присоединяет Биджапур после длительной осады.|Aurangzeb annexes Bijapur after a long siege.|Аурангзеб узак курчоодон кийин Бижапурду кошот.',[...mughal,...ahmad,...bijapur]],[1687,1707,'Голконда и напряжение империи|Golconda and imperial strain|Голконда жана империянын чыңалуусу','Голконда включена в державу. Деканские войны увеличивают расходы, но маратхское сопротивление продолжается.|Golconda is incorporated. Deccan wars increase expenditure while Maratha resistance continues.|Голконда державага кошулат. Декан согуштары чыгымдарды көбөйтөт, бирок маратха каршылыгы уланат.',[...mughal,...ahmad,...bijapur,...golconda],'influence'],[1707,1717,'Провинции после Аурангзеба|Provinces after Aurangzeb|Аурангзебден кийинки провинциялар','После смерти Аурангзеба могольские наместники продолжают управление. Ослабление центра постепенно усиливает провинциальные дворы.|After Aurangzeb’s death Mughal governors continue governing. Declining central power gradually strengthens provincial courts.|Аурангзеб өлгөндөн кийин Могол наместниктери башкарууну улантат. Борбордун алсызданышы провинция сарайларын акырындап күчөтөт.',[...mughal,...ahmad,...bijapur,...golconda],'influence',{coord:[77.22,28.65]}],
 [1717,1720,'Возвышение Бенгалии|Bengal’s rise|Бенгалиянын күчөшү','Бенгальский двор расширяет самостоятельность. Другие могольские провинции сохраняют наместников при ослабевшем императоре.|Bengal’s court gains autonomy. Other Mughal provinces retain governors under the weakened emperor.|Бенгалия сарайы өз алдынчалыгын кеңейтет. Башка Могол провинцияларында алсыз императорго караштуу наместниктер калат.',[...mughal.slice(0,4),...ahmad,...bijapur,...golconda],'influence',{coord:[77.22,28.65]}],
 [1720,1724,'Маратхи и могольские наместники|Marathas and Mughal governors|Маратхалар жана Могол наместниктери','Маратхское влияние растёт в Малве. В Декане наместники продолжают соперничать за провинциальную власть.|Maratha influence grows in Malwa. In the Deccan governors continue competing for provincial power.|Малвада маратха таасири өсөт. Деканда наместниктер провинция бийлиги үчүн атаандашат.',[mughal[0],mughal[1],mughal[3],...ahmad,...bijapur,...golconda],'influence',{coord:[77.22,28.65]}],
 [1724,1739,'Региональные дворы и делийский центр|Regional courts and the Delhi centre|Аймактык сарайлар жана Дели борбору','Хайдарабад и Ауд ведут самостоятельную политику при номинальном признании императора. Гуджарат ещё управляется могольскими наместниками.|Hyderabad and Awadh pursue autonomous policies while nominally acknowledging the emperor. Gujarat still has Mughal governors.|Хайдарабад менен Ауд императорду расмий таанып, өз алдынча саясат жүргүзөт. Гужаратта Могол наместниктери башкарууну улантат.',[mughal[0],mughal[1],mughal[3]],'influence',{coord:[77.22,28.65]}],[1739,1790,'Делийский двор при ограниченной власти|Delhi court with limited power|Чектелген бийликтеги Дели сарайы','Разграбление Дели Надир-шахом ускоряет упадок. Могольский титул сохраняется, но военная власть переходит к региональным силам.|Nader Shah’s sack of Delhi accelerates decline. The Mughal title persists while military power passes to regional forces.|Надир-шахтын Делини талап-тоноосу алсызданууну тездетет. Могол наамы сакталат, бирок аскердик бийлик аймактык күчтөргө өтөт.',delhi,'influence',{coord:[77.22,28.65]}]]);
 M('early-ahmadnagar','Deccan','#a795a8',[[1601,1636,'Малик Амбар и сопротивление Моголам|Malik Ambar and resistance to the Mughals|Малик Амбар жана Моголдорго каршылык','После потери столицы Низам-шахи продолжают борьбу. Малик Амбар опирается на подвижные войска и сельские доходы.|After losing the capital the Nizam Shahis continue fighting. Malik Ambar relies on mobile forces and rural revenue.|Борборду жоготкондон кийин Низам-шахтар күрөштү улантат. Малик Амбар кыймылдуу аскерге жана айыл кирешесине таянат.',ahmad,'influence']]);
 M('early-bijapur','Deccan','#ac9ca8',[[1601,1686,'Биджапур Адил-шахов|Adil Shahi Bijapur|Адил-шахтардын Бижапуру','Султанат поддерживает музыку, архитектуру и многоязычный двор. Войны с Моголами и маратхами сужают самостоятельность.|The sultanate supports music, architecture and a multilingual court. Wars with Mughals and Marathas restrict its independence.|Султанат музыканы, архитектураны жана көп тилдүү сарайды колдойт. Моголдор жана маратхалар менен согуштар анын өз алдынчалыгын чектейт.',bijapur]]);
 M('early-golconda','Deccan','#b4a27f',[[1601,1687,'Голконда и Хайдарабад|Golconda and Hyderabad|Голконда жана Хайдарабад','Кутб-шахи правят богатым алмазами и тканями регионом. Торговля связывает Декан с Персидским заливом и Индийским океаном.|The Qutb Shahis rule a region rich in diamonds and textiles. Trade connects the Deccan to the Persian Gulf and Indian Ocean.|Кутб-шахтар алмазга жана кездемеге бай аймакты башкарат. Соода Деканды Перс булуңу жана Инд океаны менен байланыштырат.',golconda]]);
 M('late-vijayanagara','India','#bcaa7c',[[1601,1646,'Поздние Аравиду и местные правители|Late Aravidu and local rulers|Соңку Аравиду жана жергиликтүү башкаруучулар','Наследники Виджаянагара удерживают отдельные центры, а наяки расширяют самостоятельность.|Vijayanagara’s successors retain some centres while Nayaka rulers gain autonomy.|Вижаянагаранын мураскерлери айрым борборлорду кармайт, ал эми наяктар өз алдынчалыгын кеңейтет.',null,'influence']]);
 A('south-indian-courts','Южноиндийские региональные дворы|South Indian regional courts|Түштүк Индиянын аймактык сарайлары',[78.12,9.93],'India','#baa888',[[1646,1790,'Мадурай, Танджавур и местные династии|Madurai, Thanjavur and local dynasties|Мадурай, Танжавур жана жергиликтүү династиялар','Наякские и последующие династии поддерживают города, храмы и земледелие. Это несколько владений, а не единое южноиндийское государство.|Nayaka and successor dynasties sustain towns, temples and agriculture. These are several polities, not one southern Indian state.|Наяк жана кийинки династиялар шаарларды, ибадатканаларды жана дыйканчылыкты колдойт. Булар бирдиктүү түштүк индия мамлекети эмес, бир нече ээлик.',[[77.5,8.6],[79,9],[79.8,11],[79.4,12],[77.4,11.5]],'cultural']],'region');
 A('maratha','Маратхские владения|Maratha polities|Маратха ээликтери',[73.45,18.23],'RegionalIndia','#b8a477',[[1674,1720,'Шиваджи и наследники|Shivaji and his successors|Шиважи жана анын мураскерлери','Коронация Шиваджи закрепляет царский титул. Горные крепости, сельские сборы и подвижные армии поддерживают сопротивление Моголам.|Shivaji’s coronation establishes a royal title. Hill forts, rural levies and mobile armies sustain resistance to the Mughals.|Шиважинин таажы кийүүсү падышалык наамды бекитет. Тоо чептери, айыл салыктары жана кыймылдуу аскер Моголдорго каршылыкты колдойт.',maratha,'influence'],[1720,1761,'Пешвы и маратхские дома|Peshwas and Maratha houses|Пешвалар жана маратха үйлөрү','Влияние маратхских военных домов распространяется к Мальве. Сбор дани и союзные владения не равны прямому управлению всей Индией.|Maratha military houses extend influence toward Malwa. Tribute rights and allied polities do not mean direct rule over all India.|Маратха аскердик үйлөрүнүн таасири Малвага жетет. Алым укуктары жана союздаш ээликтер бүт Индияны түз башкаруу эмес.',[maratha,malwa],'influence',{coord:[73.86,18.52]}],[1761,1790,'После Панипата|After Panipat|Панипаттан кийин','Поражение от Ахмад-шаха Дуррани не уничтожает маратхские дворы. Они восстанавливают влияние как объединение нескольких сильных домов.|Defeat by Ahmad Shah Durrani does not destroy the Maratha courts. They restore influence as an association of powerful houses.|Ахмад-шах Дурраниден жеңилүү маратха сарайларын жок кылбайт. Алар күчтүү үйлөрдүн бирикмеси катары таасирин калыбына келтирет.',[maratha,malwa],'influence',{coord:[73.86,18.52]}]]);
 A('gujarat-regional','Гуджарат · региональное управление|Gujarat · regional government|Гужарат · аймактык башкаруу',[72.58,23.02],'RegionalIndia','#b3a17e',[[1739,1753,'Могольские наместники и маратхское давление|Mughal governors and Maratha pressure|Могол наместниктери жана маратха басымы','Ослабление делийского двора не уничтожает местное управление. Наместники, купцы и маратхские силы соперничают за доходы и города.|Delhi’s decline does not end local government. Governors, merchants and Maratha forces contest revenues and towns.|Дели сарайынын алсызданышы жергиликтүү башкарууну жок кылбайт. Наместниктер, соодагерлер жана маратха күчтөрү киреше менен шаарлар үчүн атаандашат.',mughal[3],'influence'],[1753,1790,'Маратхи в Ахмадабаде|Marathas in Ahmedabad|Ахмадабаддагы маратхалар','После взятия Ахмадабада маратхские дома разделяют власть и доходы региона. Местные торговые и ремесленные сообщества продолжают жить в городе.|After Ahmedabad is captured, Maratha houses share regional authority and revenues. Local commercial and craft communities continue in the city.|Ахмадабад алынгандан кийин маратха үйлөрү аймактын бийлиги менен кирешесин бөлүшөт. Жергиликтүү соода жана кол өнөрчүлүк жамааттары шаарда жашоосун улантат.',mughal[3],'influence']],'region');
 A('bengal-nawabs','Навабы Бенгалии|Nawabs of Bengal|Бенгалия навабдары',[88.27,24.18],['RegionalIndia','India'],'#a3a78d',[[1717,1757,'Бенгальский региональный двор|Bengal’s regional court|Бенгалиянын аймактык сарайы','Навабы управляют богатой текстильной и земледельческой провинцией, формально признавая могольского императора.|Nawabs govern a rich textile-producing and agricultural province while formally acknowledging the Mughal emperor.|Навабдар Могол императорун расмий таанып, кездеме өндүргөн жана дыйканчылыгы өнүккөн бай провинцияны башкарат.',[bengal,bihar],'influence'],[1757,1765,'Навабы после Плесси|Nawabs after Plassey|Плесси салгылашуусунан кийинки навабдар','Ост-Индская компания вмешивается в смену навабов и получает всё больше военных и финансовых преимуществ.|The East India Company intervenes in nawab successions and gains military and financial advantages.|Ост-Индия компаниясы навабдардын алмашуусуна кийлигишип, аскердик жана каржылык артыкчылыктарга ээ болот.',[bengal,bihar],'influence']]);
 A('company-bengal','Бенгалия · Ост-Индская компания|Bengal · East India Company|Бенгалия · Ост-Индия компаниясы',[88.36,22.57],'India','#a3aeba',[[1765,1790,'Право сбора доходов и власть компании|Revenue rights and Company rule|Киреше чогултуу укугу жана компания бийлиги','Император предоставляет компании дивани Бенгалии и Бихара. Местные учреждения сохраняются, но доходы и военная сила переходят под контроль компании.|The emperor grants the Company the diwani of Bengal and Bihar. Local institutions remain, but revenues and military power come under Company control.|Император компанияга Бенгалия менен Бихардын дивани укугун берет. Жергиликтүү мекемелер сакталат, бирок киреше жана аскердик күч компаниянын көзөмөлүнө өтөт.',[bengal,bihar],'influence']],'region');
 A('awadh','Авадх|Awadh|Авадх',[82.14,26.78],'RegionalIndia','#afaa90',[[1722,1790,'Навабское управление в Авадхе|Nawab rule in Awadh|Авадхтагы наваб бийлиги','Региональные правители сохраняют могольские титулы, собирают доходы и поддерживают собственный двор.|Regional rulers retain Mughal titles, collect revenue and maintain their own court.|Аймак башкаруучулары могол наамдарын сактап, киреше чогултуп, өз сарайын кармайт.',awadh,'influence']]);
 A('hyderabad','Хайдарабад|Hyderabad|Хайдарабад',[78.48,17.39],'RegionalIndia','#aca19b',[[1724,1790,'Низамы в Декане|Nizams in the Deccan|Декандагы низамдар','Асаф-Джахи создают самостоятельное региональное управление при номинальной связи с Моголами.|The Asaf Jahis establish autonomous regional government with a nominal Mughal connection.|Асаф-Жахилер Моголдор менен расмий байланышты сактап, өз алдынча аймактык башкаруу түзөт.',[...golconda,...ahmad,...bijapur],'influence']]);
 A('mysore','Майсур|Mysore|Майсур',[76.65,12.42],['India','RegionalIndia'],'#b5a383',[[1601,1761,'Водеяры в Майсуре|Wodeyars of Mysore|Майсурдагы Водеярлар','Местная династия развивает власть в южном Декане после ослабления Виджаянагара.|A local dynasty expands power in the southern Deccan after Vijayanagara’s decline.|Жергиликтүү династия Вижаянагара алсыздангандан кийин түштүк Деканда бийлигин кеңейтет.',mysore],[1761,1782,'Хайдар Али|Hyder Ali|Хайдар Али','Военный руководитель Хайдар Али сосредоточивает реальную власть. Майсур воюет с маратхами и Ост-Индской компанией.|Military leader Hyder Ali concentrates effective power. Mysore fights the Marathas and the East India Company.|Аскер башчысы Хайдар Али чыныгы бийликти топтойт. Майсур маратхалар жана Ост-Индия компаниясы менен согушат.',mysore,'influence'],[1782,1790,'Типу Султан|Tipu Sultan|Типу Султан','Типу продолжает войны и укрепление государства, развивая военное производство и внешнюю дипломатию.|Tipu continues warfare and state-building, developing military production and foreign diplomacy.|Типу согуштарды жана мамлекетти бекемдөөнү улантып, аскердик өндүрүштү жана тышкы дипломатияны өнүктүрөт.',mysore,'influence']]);

