 M('angkor','SEAsia','#b3a583',[[1601,1790,'Кхмерский двор в районе Удонга|Khmer court around Oudong|Удонг аймагындагы кхмер сарайы','Камбоджийские правители сохраняют двор и местную власть, маневрируя между Сиамом и вьетнамскими силами.|Cambodian rulers retain their court and local authority while manoeuvring between Siam and Vietnamese powers.|Камбоджа башкаруучулары Сиам менен вьетнам күчтөрүнүн ортосунда саясат жүргүзүп, сарайын жана жергиликтүү бийлигин сактайт.',null,'influence',{coord:[104.7,12.1]}]]);
 M('late-ayutthaya',['Siam','SEAsia'],'#baa178',[[1601,1767,'Аюттхая: речная столица и торговый двор|Ayutthaya: river capital and trading court|Аюттхая: дарыя борбору жана соода сарайы','Двор регулирует труд и торговлю; в городе живут разные купеческие общины. Сиам соперничает с бирманскими державами.|The court regulates labour and trade; diverse merchant communities live in the city. Siam rivals Burmese powers.|Сарай эмгекти жана сооданы жөнгө салат; шаарда ар түрдүү соодагер жамааттары жашайт. Сиам Бирма державалары менен атаандашат.',siam]]);
 A('thonburi','Тхонбури|Thonburi|Тхонбури',[100.49,13.74],'Siam','#baa178',[[1767,1782,'Таксин восстанавливает сиамскую власть|Taksin restores Siamese power|Таксин Сиам бийлигин калыбына келтирет','После разрушения Аюттхаи Таксин собирает силы вокруг новой столицы на Чаупхрае.|After Ayutthaya’s destruction Taksin regroups around a new capital on the Chao Phraya.|Аюттхая кыйрагандан кийин Таксин Чаупхраядагы жаңы борбордун айланасына күч топтойт.',siam,'influence']]);
 A('bangkok','Сиам · династия Чакри|Siam · Chakri dynasty|Сиам · Чакри династиясы',[100.5,13.75],'Siam','#baa178',[[1782,1790,'Бангкок — новая столица|Bangkok as the new capital|Бангкок — жаңы борбор','Рама I переносит столицу на восточный берег реки. Новая династия восстанавливает придворные и религиозные институты.|Rama I moves the capital to the river’s eastern bank. The new dynasty restores court and religious institutions.|Рама I борборду дарыянын чыгыш жээгине көчүрөт. Жаңы династия сарай жана диний мекемелерди калыбына келтирет.',siam,'influence']]);
 M('early-toungoo','Burma','#a6a18b',[[1601,1752,'Восстановленная династия Таунгу|Restored Toungoo dynasty|Калыбына келген Таунгу династиясы','Ава вновь связывает ирравадийские центры; власть распределена между двором, городами и местными правителями.|Ava reconnects Irrawaddy centres; authority is distributed among the court, towns and local rulers.|Ава Иравади борборлорун кайра байланыштырат; бийлик сарай, шаарлар жана жергиликтүү башкаруучулар арасында бөлүштүрүлөт.',burma,'influence']]);
 A('konbaung','Конбаун|Konbaung|Конбаун',[95.57,22.57],'Burma','#a6a18b',[[1752,1757,'Алаунпая в Верхней Бирме|Alaungpaya in Upper Burma|Жогорку Бирмадагы Алаунпая','Новая династия возникает в ходе войны после падения Авы.|A new dynasty emerges during the war following Ava’s fall.|Жаңы династия Ава кулагандан кийинки согушта пайда болот.',[[94,20],[96,20],[97,23.5],[95.5,25],[94,24]],'influence'],[1757,1790,'Ирравадийская держава Конбаун|Konbaung Irrawaddy state|Конбаундун Иравади мамлекети','Династия подчиняет нижнюю долину и воюет с Сиамом и Цин. Местные дворы и общины сохраняют различия.|The dynasty subordinates the lower valley and fights Siam and the Qing. Local courts and communities retain their differences.|Династия төмөнкү өрөөндү баш ийдирип, Сиам жана Цин менен согушат. Жергиликтүү сарайлар менен жамааттар өзгөчөлүктөрүн сактайт.',burma,'influence',{coord:[95.98,21.87]}]]);
 M('late-daiviet','Vietnam','#94ac95',[[1601,1786,'Север Дайвьета: Ле и Чинь|Northern Dai Viet: Le and Trinh|Түндүк Дайвьет: Ле жана Чинь','Императоры Ле сохраняют титул, а реальная северная власть находится у Чинь. Войны с южными Нгуен разделяют страну.|Le emperors retain their title while the Trinh hold effective northern power. Wars with the southern Nguyen divide the country.|Ле императорлору наамын сактайт, ал эми түндүктөгү чыныгы бийлик Чиньде болот. Түштүктөгү Нгуен менен согуштар өлкөнү бөлөт.',vnNorth,'influence'],[1786,1789,'Падение Чинь и кризис двора Ле|Fall of the Trinh and crisis of the Le court|Чиндин кулашы жана Ле сарайынын кризиси','Тэйшоны свергли власть Чинь. Последние Ле ищут поддержку Цин.|The Tay Son overthrow the Trinh. The last Le rulers seek Qing support.|Тэйшондор Чинь бийлигин кулатат. Акыркы Ле башкаруучулары Циндин колдоосун издейт.',vnNorth,'influence']]);
 A('nguyen-lords','Южные владения Нгуен|Southern Nguyen domains|Нгуендин түштүк ээликтери',[107.59,16.46],'Vietnam','#b7a889',[[1601,1777,'Нгуен в Дангчонге|Nguyen in Dang Trong|Дангчонгдогу Нгуен','Южные правители развивают земледелие и порты, соперничая с северными Чинь. Восстание Тэйшон начинается в 1771 году.|Southern rulers develop agriculture and ports while rivalling the northern Trinh. The Tay Son uprising begins in 1771.|Түштүк башкаруучулары түндүктөгү Чинге атаандашып, дыйканчылык менен портторду өнүктүрөт. Тэйшон көтөрүлүшү 1771-жылы башталат.',vnSouth,'influence']]);
 A('tayson','Тэйшон|Tay Son|Тэйшон',[109.22,13.78],'Vietnam','#b0a190',[[1771,1786,'Восстание Тэйшон|Tay Son uprising|Тэйшон көтөрүлүшү','Братья Тэйшон поднимают восстание в центральных землях и формируют новые военные дворы.|The Tay Son brothers raise a rebellion in the central lands and form new military courts.|Тэйшон бир туугандары борбордук жерлерде көтөрүлүш чыгарып, жаңы аскердик сарайларды түзөт.',taySon,'influence'],[1786,1789,'Продвижение на север|Advance north|Түндүккө жылуу','Тэйшоны свергают Чинь и вмешиваются в дела двора Ле; между их собственными центрами сохраняется соперничество.|The Tay Son overthrow the Trinh and intervene at the Le court; their own centres remain rivals.|Тэйшондор Чинди кулатып, Ле сарайынын иштерине кийлигишет; алардын өз борборлору да атаандашат.',[taySon,vnSouth,vnNorth],'influence'],[1789,1790,'Куанг Чунг после победы над Цин|Quang Trung after victory over the Qing|Цинди жеңгенден кийинки Куанг Чунг','Победа у Тханглонга прекращает цинское вмешательство. Тэйшонские дворы и южные силы Нгуен продолжают борьбу.|Victory near Thang Long ends Qing intervention. Tay Son courts and southern Nguyen forces continue competing.|Тханглонг жанындагы жеңиш Циндин кийлигишүүсүн токтотот. Тэйшон сарайлары жана түштүктөгү Нгуен күчтөрү күрөштү улантат.',[taySon,vnSouth,vnNorth],'influence',{coord:[107.59,16.46]}]]);
 M('early-champa','Vietnam','#bca88e',[[1601,1790,'Пандуранга и чамские общины|Panduranga and Cham communities|Пандуранга жана чам жамааттары','Южные чамские правители и общины сохраняют местные институты при растущем давлении вьетнамских дворов.|Southern Cham rulers and communities retain local institutions under growing pressure from Vietnamese courts.|Түштүк чам башкаруучулары жана жамааттары вьетнам сарайларынын күчөгөн басымы алдында жергиликтүү мекемелерин сактайт.',null,'cultural']]);
 M('late-lanxang','Lao','#a8a185',[[1601,1707,'Лансанг: речные города и монастыри|Lan Xang: river towns and monasteries|Лансанг: дарыя шаарлары жана монастырлар','Двор и местные мыанги связывают общины Меконга. Борьба за наследование приводит к разделению царства.|The court and local muang connect Mekong communities. Succession disputes lead to the kingdom’s partition.|Сарай жана жергиликтүү мыангдар Меконг жамааттарын байланыштырат. Мурас үчүн күрөш падышалыктын бөлүнүшүнө алып келет.',null,'influence',{coord:[102.62,17.97]}]]);
 A('lao-kingdoms','Лаосские царства|Lao kingdoms|Лаос падышалыктары',[102.14,19.88],['Lao','Siam'],'#a8a185',[[1707,1779,'Луангпхабанг и Вьентьян|Luang Prabang and Vientiane|Луангпрабанг жана Вьентьян','После разделения Лансанга существуют отдельные дворы. Речные города и монастыри сохраняют общую культурную среду.|Separate courts exist after Lan Xang’s division. River towns and monasteries retain a shared cultural world.|Лансанг бөлүнгөндөн кийин өзүнчө сарайлар жашайт. Дарыя шаарлары жана монастырлар жалпы маданий чөйрөнү сактайт.',[laoNorth,laoCentral],'influence'],[1779,1790,'Лаосские дворы под сиамским верховенством|Lao courts under Siamese suzerainty|Сиам үстөмдүгүндөгү лаос сарайлары','Сиамские походы устанавливают зависимость. Местные правители продолжают управлять своими общинами.|Siamese campaigns establish dependency. Local rulers continue governing their communities.|Сиам жортуулдары көз карандылыкты орнотот. Жергиликтүү башкаруучулар жамааттарын башкарууну улантат.',[laoNorth,laoCentral],'influence']],'region');
 M('early-portuguese-malacca','SEAsia','#a4a9ab',[[1601,1641,'Португальская Малакка|Portuguese Malacca|Португал Малаккасы','Крепость и порт участвуют в борьбе за пролив с Джохором, Ачехом и нидерландцами.|The fortress and port contest the strait with Johor, Aceh and the Dutch.|Чеп менен порт кысык үчүн Жохор, Ачех жана нидерланддар менен күрөшөт.',null,'settlement']]);
 A('dutch-malacca','Малакка · нидерландская компания|Malacca · Dutch Company|Малакка · нидерланд компаниясы',[102.25,2.19],'SEAsia','#9faab3',[[1641,1790,'Малакка после совместного завоевания|Malacca after the joint conquest|Биргелешкен каратуудан кийинки Малакка','Нидерландцы при поддержке Джохора берут порт. Контроль компании над крепостью не означает власть над всей Малаккской землёй.|The Dutch take the port with Johor’s support. Company control of the fort does not mean rule over the whole Malay Peninsula.|Нидерланддар Жохордун колдоосу менен портту алат. Компаниянын чепти көзөмөлдөшү бүт Малакка жарым аралына бийлик жүргүзүү эмес.',G('early-portuguese-malacca'),'settlement']],'city');
 M('early-johor','SEAsia','#9da993',[[1601,1641,'Джохор между Ачехом и Португалией|Johor between Aceh and Portugal|Ачех менен Португалиянын ортосундагы Жохор','Малайский двор сохраняет речные опорные пункты и заключает союз с нидерландцами.|The Malay court retains river strongholds and allies with the Dutch.|Малай сарайы дарыя таянычтарын сактап, нидерланддар менен союз түзөт.',null,'influence'],[1641,1790,'Джохор-Риау и морские сети|Johor-Riau and maritime networks|Жохор-Риау жана деңиз тармактары','После падения португальской Малакки торговые сети Джохора расширяются; династические споры и бугийские силы меняют управление.|After Portuguese Malacca falls, Johor’s trading networks expand; dynastic disputes and Bugis forces reshape government.|Португал Малаккасы кулагандан кийин Жохордун соода тармактары кеңейет; династиялык талаштар жана буги күчтөрү башкарууну өзгөртөт.',null,'influence']]);
 M('early-java-sultanates','Java','#a6aa86',[[1601,1755,'Матарам и яванские дворы|Mataram and Javanese courts|Матарам жана Ява сарайлары','Дворы соперничают между собой и с нидерландской компанией. Земледельческий внутренний район сохраняет самостоятельные центры.|Courts compete with each other and with the Dutch Company. The agricultural interior retains its own centres.|Сарайлар бири-бири жана нидерланд компаниясы менен атаандашат. Дыйканчылык өнүккөн ички аймак өз борборлорун сактайт.',java,'influence'],[1755,1790,'Джокьякарта и Суракарта|Yogyakarta and Surakarta|Жокьякарта жана Суракарта','Раздел Матарама создаёт отдельные династические дворы при усилившемся влиянии компании.|Mataram’s division creates separate dynastic courts under growing Company influence.|Матарамдын бөлүнүшү компаниянын күчөгөн таасири алдында өзүнчө династиялык сарайларды түзөт.',java,'influence']]);
 A('batavia','Батавия · нидерландская компания|Batavia · Dutch Company|Батавия · нидерланд компаниясы',[106.82,-6.13],'Java','#9faab3',[[1619,1790,'Укреплённый торговый и административный центр|Fortified commercial and administrative centre|Бекемделген соода жана башкаруу борбору','Компания строит Батавию после разрушения Джаякарты. Город связывает азиатскую торговлю, миграцию и принудительный труд.|The Company builds Batavia after destroying Jayakarta. The city connects Asian commerce, migration and coerced labour.|Компания Жаякартаны талкалагандан кийин Батавияны курат. Шаар Азия соодасын, миграцияны жана мажбур эмгекти байланыштырат.',[[106.5,-6.5],[107.2,-6.5],[107.2,-5.95],[106.5,-5.95]],'settlement']],'city');
 M('early-manila',['SEAsia','Manila'],'#a3aab6',[[1601,1762,'Испанская Манила и галеонная торговля|Spanish Manila and the galleon trade|Испан Маниласы жана галеон соодасы','Манила связывает азиатские товары с американским серебром. Китайские, местные и европейские общины формируют портовый город.|Manila links Asian goods with American silver. Chinese, local and European communities shape the port city.|Манила Азия товарларын Америка күмүшү менен байланыштырат. Кытай, жергиликтүү жана Европа жамааттары порттук шаарды түзөт.',null,'settlement'],[1762,1764,'Британская оккупация Манилы|British occupation of Manila|Маниланын британ оккупациясы','Британская экспедиция занимает столицу в ходе Семилетней войны. Большая часть архипелага не переходит под её контроль.|A British expedition occupies the capital during the Seven Years’ War. Most of the archipelago does not fall under its control.|Британ экспедициясы Жети жылдык согушта борборду ээлейт. Архипелагдын көп бөлүгү анын көзөмөлүнө өтпөйт.',null,'settlement'],[1764,1790,'Возвращение испанского управления|Spanish administration restored|Испан башкаруусунун кайтарылышы','После ухода британских сил порт возвращается под испанское управление.|After British forces withdraw the port returns to Spanish administration.|Британ күчтөрү кеткенден кийин порт испан башкаруусуна кайтып келет.',null,'settlement']]);
 M('early-cebu','SEAsia','#a3aab6',[[1601,1790,'Себу и висайские связи|Cebu and Visayan connections|Себу жана Висай байланыштары','Испанские учреждения действуют в портовом центре рядом с местными общинами и межостровной торговлей.|Spanish institutions operate in the port centre alongside local communities and inter-island trade.|Испан мекемелери порттук борбордо жергиликтүү жамааттар жана арал аралык соода менен катар иштейт.',null,'settlement']]);

