 const england=G('late-england'),scotland=G('early-scotland'),castile=G('late-castile'),aragon=G('late-aragon'),france=G('late-france'),navarre=G('late-navarre'),poland=G('early-commonwealth'),commonReduced=[poland[0],[[22,54],[24,51],[27,48.5],[30.3,49],[30,52],[31.5,54.8],[28,56],[23,56.2]]],poland1772=[[[17.5,50.2],[20,50.2],[23,50.4],[24,51.2],[22,53.5],[19,53.5],[17.5,52.5]],[[22,54],[24,51.2],[27,50],[29,50],[29.3,54.8],[26,55.8],[23,56]]],galicia=[[20,49],[23,48.5],[26,48.3],[26,49.7],[23,50.5],[20,50.2]],belarusEast=[[29.5,53],[32,53],[32.2,55.5],[29.5,55.7]],brandenburg=[[11.5,51.5],[14.8,51.4],[15.5,53],[13.8,53.8],[11.4,53]],eastPrussia=[[19.5,53.5],[22.8,53.4],[23,55],[21,55.5],[19.5,54.7]],silesia=[[15,50.4],[17,49.8],[18.5,50.3],[18,51.5],[16,52],[14.8,51.5]],westPrussia=[[17,53.2],[18.8,53.25],[19.5,53.7],[19.5,54.2],[18.2,54.1],[17,54.4]],finland=[[21,60],[25,59.8],[29,61],[29,65],[26,67],[23,65],[21,62]];
 M('late-castile','Iberia','#b49d85',[[1601,1700,'Кастилия в испанской монархии|Castile in the Spanish monarchy|Испан монархиясындагы Кастилия','Кастилия несёт значительную часть налоговых и военных расходов составной монархии Габсбургов.|Castile bears much of the tax and military burden of the composite Habsburg monarchy.|Кастилия Габсбургдардын курама монархиясынын салык жана аскердик чыгымдарынын олуттуу бөлүгүн көтөрөт.',castile],[1700,1716,'Бурбоны и война за наследство|Bourbons and the succession war|Бурбондор жана мурас үчүн согуш','Смерть Карла II вызывает европейскую войну. Филипп V удерживает испанскую корону.|Charles II’s death triggers a European war. Philip V retains the Spanish crown.|Карл IIнин өлүмү Европа согушуна алып келет. Филипп V испан таажысын сактайт.',castile]]);
 M('late-aragon','Iberia','#b49d85',[[1601,1707,'Арагонская корона в составной монархии|Crown of Aragon in a composite monarchy|Курама монархиядагы Арагон таажысы','Арагонские земли сохраняют собственные учреждения при общем испанском монархе.|Aragonese lands retain their institutions under a shared Spanish monarch.|Арагон жерлери жалпы испан монархы алдында өз мекемелерин сактайт.',aragon],[1707,1716,'Новая Планта и изменение учреждений|Nueva Planta and institutional change|Нуэва-Планта жана мекемелердин өзгөрүшү','Бурбонские декреты последовательно меняют управление Арагона, Валенсии и Каталонии; каталонский декрет принят в 1716 году.|Bourbon decrees progressively reorganise Aragon, Valencia and Catalonia; the Catalan decree is issued in 1716.|Бурбон жарлыктары Арагон, Валенсия жана Каталониянын башкаруусун акырындап өзгөртөт; Каталония жарлыгы 1716-жылы кабыл алынат.',aragon,'influence']]);
 A('spain','Испанская монархия|Spanish monarchy|Испан монархиясы',[-3.7,40.42],'Iberia','#b49d85',[[1716,1790,'Бурбонская Испания|Bourbon Spain|Бурбон Испаниясы','После войны за наследство управление становится более централизованным. Атлантические связи сохраняют важность для хозяйства и казны.|After the succession war government becomes more centralised. Atlantic connections remain important to the economy and treasury.|Мурас согушунан кийин башкаруу көбүрөөк борборлошот. Атлантика байланыштары чарба жана казына үчүн маанилүү бойдон калат.',[...castile,...aragon]]]);
 M('late-portugal','Iberia','#9aa990',[[1601,1640,'Португалия при общем монархе Габсбургов|Portugal under a shared Habsburg monarch|Жалпы Габсбург монархы алдындагы Португалия','Португалия сохраняет отдельные учреждения и заморские связи в династической унии.|Portugal retains separate institutions and overseas connections within a dynastic union.|Португалия династиялык унияда өзүнчө мекемелерин жана деңиз ары байланыштарын сактайт.'],[1640,1790,'Браганса и восстановленная монархия|Braganza and the restored monarchy|Браганса жана калыбына келген монархия','Браганса восстанавливают самостоятельную корону. Лиссабон связывает атлантическую торговлю; землетрясение 1755 года ведёт к перестройке столицы.|The Braganzas restore a separate crown. Lisbon connects Atlantic trade; the 1755 earthquake leads to rebuilding the capital.|Брагансалар өзүнчө таажыны калыбына келтирет. Лиссабон Атлантика соодасын байланыштырат; 1755-жылкы жер титирөө борборду кайра курууга алып келет.']]);
 M('late-navarre','Europe','#9aabac',[[1601,1620,'Нижняя Наварра при французском короле|Lower Navarre under the French king|Француз королу алдындагы Төмөнкү Наварра','Династическая связь с французской короной предшествует административному включению.|A dynastic connection to the French crown precedes administrative incorporation.|Француз таажысы менен династиялык байланыш башкаруучулук кошулуудан мурда түзүлөт.',navarre]]);
 M('late-france',['Europe','France'],'#9aabac',[[1601,1620,'Бурбонское восстановление|Bourbon recovery|Бурбондордун калыбына келиши','Корона восстанавливает управление после религиозных войн.|The crown restores government after the Wars of Religion.|Таажы диний согуштардан кийин башкарууну калыбына келтирет.',france],[1620,1789,'Королевская Франция|Royal France|Королдук Франция','Монархия усиливает армию, налоги и управление. Двор, города и печатная культура становятся центрами европейского влияния.|The monarchy strengthens armies, taxation and administration. Court, cities and print culture become centres of European influence.|Монархия аскерди, салыкты жана башкарууну күчөтөт. Сарай, шаарлар жана басма маданияты Европадагы таасир борборлоруна айланат.',[...france,...navarre]],[1789,1790,'Начало Французской революции|Beginning of the French Revolution|Француз революциясынын башталышы','Генеральные штаты превращаются в Национальное собрание. Взятие Бастилии и отмена сословных привилегий меняют порядок; Франция ещё остаётся монархией.|The Estates General becomes a National Assembly. The fall of the Bastille and abolition of estate privileges change the order; France remains a monarchy.|Генералдык штаттар Улуттук жыйынга айланат. Бастилиянын алынышы жана сословиелик артыкчылыктардын жоюлушу тартипти өзгөртөт; Франция али монархия бойдон калат.',[...france,...navarre]]]);
 M('late-england','Britain','#ac9d91',[[1601,1649,'Монархия, парламент и гражданские войны|Monarchy, Parliament and civil wars|Монархия, парламент жана жарандык согуштар','С 1603 года Англия и Шотландия имеют общего монарха, но отдельные учреждения. Конфликт короны и парламента перерастает в войны.|From 1603 England and Scotland share a monarch but retain separate institutions. Crown–Parliament conflict becomes war.|1603-жылдан Англия менен Шотландиянын монархы жалпы, бирок мекемелери өзүнчө. Таажы менен парламенттин жаңжалы согушка айланат.',england],[1649,1660,'Республика и протекторат|Commonwealth and Protectorate|Республика жана протекторат','После казни Карла I монархия упразднена. Парламент и армия ищут новый порядок; Кромвель становится лордом-протектором в 1653 году.|After Charles I’s execution the monarchy is abolished. Parliament and army seek a new order; Cromwell becomes Lord Protector in 1653.|Карл I өлүм жазасына тартылгандан кийин монархия жоюлат. Парламент менен аскер жаңы тартип издейт; Кромвелл 1653-жылы лорд-протектор болот.',england],[1660,1707,'Реставрация и парламентская монархия|Restoration and parliamentary monarchy|Калыбына келүү жана парламенттик монархия','Монархия восстановлена. Перемены 1688–1689 годов усиливают роль парламента.|The monarchy is restored. The changes of 1688–1689 strengthen Parliament’s role.|Монархия калыбына келтирилет. 1688–1689-жылдардагы өзгөрүүлөр парламенттин ролун күчөтөт.',england]]);
 M('early-scotland','Britain','#ac9d91',[[1601,1651,'Шотландская корона и общий монарх|Scottish crown and a shared monarch|Шотланд таажысы жана жалпы монарх','Шотландия сохраняет собственный парламент и церковь при династической связи с Англией с 1603 года.|Scotland retains its Parliament and church within the dynastic union with England from 1603.|Шотландия 1603-жылдан Англия менен династиялык байланышта өз парламентин жана чиркөөсүн сактайт.',scotland],[1651,1660,'Английское военное господство|English military domination|Англиянын аскердик үстөмдүгү','После поражений шотландская территория включается в республиканский режим под английским военным контролем.|Following military defeats Scotland is incorporated into the republican regime under English military control.|Аскердик жеңилүүлөрдөн кийин Шотландия Англиянын аскердик көзөмөлүндөгү республикалык түзүлүшкө киргизилет.',scotland,'influence'],[1660,1707,'Восстановленное королевство|Restored kingdom|Калыбына келген падышалык','При общей династии Шотландия вновь имеет отдельные учреждения до парламентской унии.|Under a shared dynasty Scotland again has separate institutions until parliamentary union.|Жалпы династия алдында Шотландия парламенттик унияга чейин кайра өзүнчө мекемелерге ээ болот.',scotland]]);
 A('great-britain','Великобритания|Great Britain|Улуу Британия',[-0.13,51.51],'Britain','#ac9d91',[[1707,1790,'Уния Англии и Шотландии|Union of England and Scotland|Англия менен Шотландиянын униясы','Создан единый парламент Великобритании. Шотландские право и церковь сохраняются; морская торговля и промышленное производство растут.|A single Parliament of Great Britain is created. Scots law and the Scottish church remain; maritime trade and industrial production grow.|Улуу Британиянын бирдиктүү парламенти түзүлөт. Шотланд укугу жана чиркөөсү сакталат; деңиз соодасы жана өнөр жай өндүрүшү өсөт.',[...england,...scotland]]]);
 M('late-hre','Europe','#b0a895',[[1601,1648,'Имперские сословия и Тридцатилетняя война|Imperial estates and the Thirty Years’ War|Империялык сословиелер жана Отуз жылдык согуш','Княжества, города и император участвуют в конфессиональных и династических конфликтах. Война с 1618 года разрушает многие земли.|Principalities, cities and emperor take part in confessional and dynastic conflicts. War from 1618 devastates many regions.|Княздыктар, шаарлар жана император диний жана династиялык жаңжалдарга катышат. 1618-жылдан согуш көп жерди кыйратат.',null,'influence'],[1648,1790,'Империя после Вестфальского мира|Empire after Westphalia|Вестфаль тынчтыгынан кийинки империя','Мир закрепляет права имперских сословий. Империя продолжает существовать как сложный союз, а не единое централизованное государство.|Peace confirms the rights of imperial estates. The empire continues as a complex association rather than a centralised state.|Тынчтык империялык сословиелердин укуктарын бекитет. Империя борборлошкон бир мамлекет эмес, татаал бирикме катары жашоосун улантат.',null,'influence']]);
 M('early-dutch','Dutch','#a0aeb4',[[1601,1648,'Республика в войне с Испанией|Republic at war with Spain|Испания менен согушкан республика','Провинции совместно ведут войну и развивают морскую торговлю.|The provinces wage war together and develop maritime trade.|Провинциялар бирге согуш жүргүзүп, деңиз соодасын өнүктүрөт.'],[1648,1790,'Признанная Нидерландская республика|Recognised Dutch Republic|Таанылган Нидерланд республикасы','Мюнстерский мир подтверждает независимость. Провинциальные штаты и городские элиты управляют торговой республикой.|The Peace of Münster confirms independence. Provincial estates and urban elites govern the commercial republic.|Мюнстер тынчтыгы эгемендикти бекитет. Провинция штаттары жана шаар төбөлдөрү соода республикасын башкарат.']]);
 M('early-netherlands','Habsburg','#af9caa',[[1601,1714,'Южные Нидерланды под испанской короной|Southern Netherlands under the Spanish crown|Испан таажысы алдындагы Түштүк Нидерланддар','Южные провинции сохраняют отдельную от республики судьбу; войны европейских держав меняют контроль над крепостями.|The southern provinces remain distinct from the republic; European wars change control of fortresses.|Түштүк провинциялар республикадан өзүнчө жолду кармайт; Европа согуштары чептердин көзөмөлүн өзгөртөт.',null,'influence'],[1714,1790,'Австрийские Нидерланды|Austrian Netherlands|Австрия Нидерланддары','Южные провинции переходят австрийской ветви Габсбургов и сохраняют местные учреждения.|The southern provinces pass to the Austrian Habsburgs while retaining local institutions.|Түштүк провинциялар жергиликтүү мекемелерин сактап, Австрия Габсбургдарына өтөт.']]);

 // Located milestones. A raid or treaty is an event, not automatically a new province.
 E('tokugawa',1603,'japan',[139.75,35.68],'Учреждение сёгуната Токугава|Tokugawa shogunate established|Токугава сёгунатынын түзүлүшү','Иэясу получает титул сёгуна; военное правительство располагается в Эдо.|Ieyasu receives the shogunal title; the military government is based in Edo.|Иэясу сёгун наамын алат; аскердик өкмөт Эдодо жайгашат.','Japan');
 E('yeniseysk',1619,'1789-siberian-river-centres',[92.18,58.45],'Основание Енисейского острога|Yeniseysk fort founded|Енисей чебинин негизделиши','Острог становится новым узлом российских речных путей и ясачного сбора.|The fort becomes a new hub of Russian river routes and tribute collection.|Чеп орус дарыя жолдорунун жана ясак жыйноонун жаңы түйүнү болот.','Siberia');
 E('batavia-founded',1619,'1789-batavia',[106.82,-6.13],'Разрушение Джаякарты и основание Батавии|Jayakarta destroyed and Batavia founded|Жаякартанын талкаланышы жана Батавиянын негизделиши','Нидерландская компания создаёт укреплённый центр на месте Джаякарты.|The Dutch Company establishes a fortified centre on Jayakarta’s site.|Нидерланд компаниясы Жаякартанын ордуна бекемделген борбор түзөт.','Java','war');
 E('yakutsk',1632,'1789-siberian-river-centres',[129.7,62.03],'Ленский острог — будущий Якутск|Lena fort — the future Yakutsk|Лена чеби — болочок Якутск','Новый острог расширяет сеть ясачных и торговых центров на Лене.|The new fort extends tribute and trading centres on the Lena.|Жаңы чеп Ленадагы ясак жана соода борборлорунун тармагын кеңейтет.','Siberia');
 E('yemen-withdrawal',1635,'1789-qasimid',[43.25,13.32],'Османские войска покидают Моху|Ottoman troops leave Mocha|Осмон аскерлеринин Мохадан кетиши','Уход гарнизона завершает первый османский период в Йемене.|The garrison’s withdrawal ends the first Ottoman period in Yemen.|Гарнизондун кетиши Йемендеги биринчи Осмон доорун аяктатат.','Arabia','war');
 E('baghdad-return',1638,'late-ottoman',[44.37,33.32],'Мурад IV берёт Багдад|Murad IV captures Baghdad|Мурад IV Багдадды алат','Город возвращается под османскую власть после сефевидского периода.|The city returns to Ottoman rule after the Safavid period.|Шаар Сефеви доорунан кийин Осмон бийлигине кайтып келет.','Ottoman','war');
 E('malacca-dutch',1641,'1789-dutch-malacca',[102.25,2.19],'Нидерландцы и Джохор берут Малакку|Dutch and Johor forces take Malacca|Нидерланд жана Жохор күчтөрү Малакканы алат','Совместная осада завершает португальское управление портом.|A joint siege ends Portuguese rule of the port.|Биргелешкен курчоо порттогу португал башкаруусун аяктатат.','SEAsia','war');
 E('qing-beijing',1644,'1789-qing',[116.4,39.9],'Цин занимает Пекин|Qing takes Beijing|Цин Пекинди алат','Пекин становится цинской столицей; завоевание остальных минских земель продолжается.|Beijing becomes the Qing capital; conquest of the remaining Ming lands continues.|Пекин Цин борбору болот; калган Мин жерлерин каратуу уланат.','China','war');
 E('westphalia',1648,'late-hre',[7.63,51.96],'Вестфальский мир|Peace of Westphalia|Вестфаль тынчтыгы','Договоры в Мюнстере и Оснабрюке завершают Тридцатилетнюю войну и пересматривают имперский порядок.|Treaties at Münster and Osnabrück end the Thirty Years’ War and revise the imperial order.|Мюнстер жана Оснабрюк келишимдери Отуз жылдык согушту аяктап, империялык тартипти өзгөртөт.','Europe','diplomacy');
 E('muscat',1650,'1789-oman',[58.55,23.6],'Оманцы берут Маскат|Omani forces take Muscat|Оман күчтөрү Маскатты алат','Ярубиды вытесняют португальский гарнизон из укреплённого порта.|The Ya‘rubids expel the Portuguese garrison from the fortified port.|Ярубилер португал гарнизонун бекемделген порттон сүрүп чыгарат.','Arabia','war');
 E('irkutsk',1661,'1789-siberian-river-centres',[104.3,52.28],'Основание Иркутского острога|Irkutsk fort founded|Иркутск чебинин негизделиши','Острог на Ангаре становится центром связей с Прибайкальем.|The Angara fort becomes a hub connecting the Baikal region.|Ангарадагы чеп Байкал аймагы менен байланыштын борбору болот.','Siberia');
 E('taiwan-zheng-takeover',1662,'1789-taiwan-zheng',[120.16,23],'Чжэн Чэнгун берёт Зеландию|Zheng Chenggong takes Zeelandia|Чжэн Чэнгун Зеландияны алат','Капитуляция нидерландской крепости открывает период власти Чжэн на юго-западе Тайваня.|The Dutch fortress’s surrender begins Zheng rule in southwestern Taiwan.|Нидерланд чебинин багынышы Тайвандын түштүк-батышында Чжэн бийлигин баштайт.','Taiwan','war');
 E('andrusovo',1667,'early-russia',[31.18,54.27],'Андрусовское перемирие|Truce of Andrusovo|Андрусово жарашуусу','Россия и Речь Посполитая закрепляют раздел спорных земель; Левобережье остаётся за Россией.|Russia and the Commonwealth settle the division of disputed lands; the left-bank territory remains with Russia.|Орусия менен Речь Посполита талаштуу жерлердин бөлүнүшүн бекитет; сол жээк Орусияда калат.','Andrusovo','diplomacy');
 E('shivaji-coronation',1674,'1789-maratha',[73.45,18.23],'Коронация Шиваджи в Райгаде|Shivaji’s coronation at Raigad|Шиважинин Райгадда таажы кийүүсү','Шиваджи утверждает царское достоинство маратхского двора.|Shivaji asserts the royal status of the Maratha court.|Шиважи маратха сарайынын падышалык даражасын бекитет.','RegionalIndia');
 E('taiwan-conquest',1683,'1789-taiwan-qing',[120.2,23],'Чжэн признают Цин|Zheng submission to the Qing|Чжэндин Цинге баш ийиши','После поражения на Пэнху правители Чжэн капитулируют. Цин устанавливает управление западным Тайванем.|After defeat at Penghu the Zheng rulers surrender. Qing administration is established in western Taiwan.|Пэнхудагы жеңилүүдөн кийин Чжэн башкаруучулары багынат. Цин батыш Тайванда башкаруу орнотот.','Taiwan','war');
 E('vienna',1683,'late-ottoman',[16.37,48.21],'Снятие осады Вены|Siege of Vienna relieved|Венанын курчоодон бошотулушу','Союзная армия разбивает османские силы у Вены. Османское отступление продолжается в последующих кампаниях.|An allied army defeats Ottoman forces near Vienna. Ottoman retreat continues in subsequent campaigns.|Союздаш аскер Вена жанында Осмон күчтөрүн жеңет. Осмондордун чегинүүсү кийинки жортуулдарда уланат.','Ottoman','war');
 E('golconda',1687,'early-mughal',[78.4,17.38],'Падение Голконды|Fall of Golconda|Голконданы алуу','Могольская армия берёт крепость; власть Кутб-шахов заканчивается.|The Mughal army takes the fortress; Qutb Shahi rule ends.|Могол аскери чепти алат; Кутб-шах бийлиги аяктайт.','Deccan','war');
 E('nerchinsk',1689,'1789-siberian-river-centres',[116.58,51.99],'Нерчинский договор|Treaty of Nerchinsk|Нерчинск келишими','Россия и Цин согласуют границу; российские силы оставляют Албазин. Обе державы развивают договорные торговые отношения.|Russia and the Qing agree a frontier; Russian forces abandon Albazin. Both states develop treaty-based trade.|Орусия менен Цин чек араны макулдашат; орус күчтөрү Албазинден кетет. Эки держава келишимге негизделген сооданы өнүктүрөт.','Nerchinsk','diplomacy');
 E('karlowitz',1699,'late-ottoman',[19.94,45.2],'Карловицкий мир|Treaty of Karlowitz|Карловиц тынчтыгы','Договор закрепляет крупные территориальные потери Османов в Европе.|The treaty confirms major Ottoman territorial losses in Europe.|Келишим Осмондордун Европадагы ири аймактык жоготууларын бекитет.','Ottoman','diplomacy');
 E('yenisei-kyrgyz-deportation',1703,'1789-yenisei-communities',[91.4,53.7],'Переселение енисейских кыргызов в Джунгарию|Deportation of Yenisei Kyrgyz to Dzungaria|Енисей кыргыздарынын Жуңгарияга көчүрүлүшү','Джунгарские власти переселяют значительную часть енисейских кыргызов. Дальнейшая судьба отдельных групп изучена неравномерно.|Dzungar authorities deport a substantial part of the Yenisei Kyrgyz. The later histories of individual groups are unevenly documented.|Жуңгар бийлиги енисей кыргыздарынын олуттуу бөлүгүн көчүрөт. Айрым топтордун кийинки тагдыры бирдей деңгээлде изилденген эмес.','Kyrgyz','migration');
 E('britain-union',1707,'1789-great-britain',[-0.13,51.51],'Образование Великобритании|Great Britain formed|Улуу Британиянын түзүлүшү','Акты об унии создают единое королевство и парламент Англии и Шотландии.|Acts of Union establish a single kingdom and Parliament for England and Scotland.|Уния актылары Англия менен Шотландиянын бирдиктүү падышалыгын жана парламентин түзөт.','Britain');
 E('nystad',1721,'1789-russian-empire',[21.41,60.8],'Ништадтский мир|Treaty of Nystad|Ништадт тынчтыгы','Россия и Швеция заканчивают Северную войну. Швеция уступает балтийские владения, сохраняя основную Финляндию.|Russia and Sweden end the Great Northern War. Sweden cedes Baltic possessions while retaining most of Finland.|Орусия менен Швеция Түндүк согушту аяктайт. Швеция Финляндиянын көп бөлүгүн сактап, Балтика ээликтерин берет.','Russia','diplomacy');
 E('isfahan-falls',1722,'1789-hotak',[51.67,32.65],'Падение Исфахана|Fall of Isfahan|Исфахандын кулашы','После длительной осады Хотаки принимают капитуляцию сефевидского двора.|After a long siege the Hotaks receive the Safavid court’s surrender.|Узак курчоодон кийин Хотакилер Сефеви сарайынын багынышын кабыл алат.','Iran','war');
 E('nader-coronation',1736,'1789-afsharid',[48.5,39.2],'Надир принимает шахский титул|Nader assumes the shah’s title|Надир шах наамын алат','На собрании в Муганской степи Надир устанавливает афшаридскую династию.|At an assembly on the Mughan plain Nader establishes the Afsharid dynasty.|Муган талаасындагы жыйында Надир Афшар династиясын түзөт.','Iran');
 E('delhi-sack',1739,'early-mughal',[77.22,28.65],'Разграбление Дели Надир-шахом|Nader Shah sacks Delhi|Надир-шахтын Делини талап-тоноосу','Победа Надира приводит к захвату сокровищ и массовым убийствам в столице. Могольский двор продолжает существовать.|Nader’s victory brings seizure of treasure and mass killing in the capital. The Mughal court continues to exist.|Надирдин жеңиши казынаны тартып алууга жана борбордогу массалык кыргынга алып келет. Могол сарайы жашоосун улантат.','Iran','war');
 E('durrani-election',1747,'1789-durrani',[65.75,31.6],'Ахмад-шах избран в Кандагаре|Ahmad Shah elected at Kandahar|Ахмад-шахтын Кандагарда шайланышы','Собрание вождей выбирает Ахмад-хана; формируется Дурранийская держава.|An assembly of chiefs chooses Ahmad Khan; the Durrani state takes shape.|Башчылардын жыйыны Ахмад-ханды тандайт; Дуррани мамлекети калыптанат.','Afghanistan');
 E('dzungar-conquest',1755,'1789-qing',[81.3,43.9],'Цинские войска входят в Или|Qing forces enter Ili|Цин аскерлери Илеге кирет','Пленение Даваци открывает новый этап завоевания Джунгарии. Сопротивление продолжается.|Dawachi’s capture opens a new stage in Dzungaria’s conquest. Resistance continues.|Давацинин туткунга алынышы Жуңгарияны каратуунун жаңы этабын ачат. Каршылык уланат.','Frontier','war');
 E('lisbon-earthquake',1755,'late-portugal',[-9.14,38.72],'Лиссабонское землетрясение|Lisbon earthquake|Лиссабон жер титирөөсү','Землетрясение, пожары и цунами разрушают столицу; восстановление меняет планировку города.|Earthquake, fires and tsunami devastate the capital; reconstruction changes its layout.|Жер титирөө, өрт жана цунами борборду кыйратат; калыбына келтирүү шаардын планын өзгөртөт.','Iberia','nature');
 E('plassey',1757,'1789-bengal-nawabs',[88.24,23.8],'Битва при Плесси|Battle of Plassey|Плесси салгылашуусу','Победа компании и переход Мир Джафара на её сторону меняют власть в Бенгалии.|Company victory and Mir Jafar’s defection change power in Bengal.|Компаниянын жеңиши жана Мир Жафардын анын тарабына өтүшү Бенгалиядагы бийликти өзгөртөт.','India','war');
 E('tarim-conquest',1759,'1789-qing',[76,39.45],'Цинское завоевание Таримских оазисов|Qing conquest of the Tarim oases|Циндин Тарим оазистерин каратуусу','Цин завершает войну с ходжами и устанавливает управление через военные центры и местных беков.|The Qing ends the war against the khojas and establishes administration through garrisons and local begs.|Цин кожолор менен согушту аяктап, аскердик борборлор жана жергиликтүү бектер аркылуу башкаруу орнотот.','Frontier','war');
 E('panipat',1761,'1789-maratha',[76.97,29.39],'Третья битва при Панипате|Third Battle of Panipat|Панипаттагы үчүнчү салгылашуу','Ахмад-шах Дуррани и его союзники разбивают маратхскую армию. Маратхские дворы позднее восстанавливают влияние.|Ahmad Shah Durrani and his allies defeat the Maratha army. Maratha courts later recover influence.|Ахмад-шах Дуррани жана союздаштары маратха аскерин жеңет. Маратха сарайлары кийин таасирин калыбына келтирет.','RegionalIndia','war');
 E('bengal-diwani',1765,'1789-company-bengal',[81.85,25.44],'Компания получает дивани|Company receives the diwani|Компания дивани укугун алат','Могольский император передаёт компании право сбора доходов Бенгалии и Бихара.|The Mughal emperor grants the Company revenue-collection rights in Bengal and Bihar.|Могол императору компанияга Бенгалия менен Бихарда киреше чогултуу укугун берет.','India','diplomacy');
 E('ayutthaya-fall',1767,'1789-thonburi',[100.56,14.35],'Разрушение Аюттхаи|Destruction of Ayutthaya|Аюттхаянын кыйратылышы','Бирманские войска разрушают столицу. Сиамское государство восстанавливается вокруг Тхонбури.|Burmese forces destroy the capital. Siamese state power is rebuilt around Thonburi.|Бирма аскерлери борборду кыйратат. Сиам мамлекетинин бийлиги Тхонбуринин айланасында калыбына келет.','Siam','war');
 E('crimea-annexation',1783,'1789-russian-empire',[33.86,44.75],'Российское присоединение Крыма|Russian annexation of Crimea|Крымдын Орусияга кошулушу','Манифест Екатерины II объявляет присоединение Крыма; ханская государственность заканчивается.|Catherine II’s manifesto declares Crimea’s annexation; khanly statehood ends.|Екатерина IIнин манифести Крымдын кошулушун жарыялайт; хандык мамлекеттүүлүк аяктайт.','Russia');
 E('bastille',1789,'late-france',[2.37,48.85],'Взятие Бастилии|Storming of the Bastille|Бастилиянын алынышы','Парижане берут крепость 14 июля. Событие становится символом революции, начавшей преобразование монархии.|Parisians take the fortress on 14 July. It becomes a symbol of the revolution transforming the monarchy.|Париждиктер 14-июлда чепти алат. Окуя монархияны өзгөрткөн революциянын символуна айланат.','France','politics');
 E('tayson-qing',1789,'1789-tayson',[105.82,21],'Победа Тэйшон у Тханглонга|Tay Son victory near Thang Long|Тханглонг жанындагы Тэйшон жеңиши','Нгуен Хюэ разбивает цинскую армию; затем стороны восстанавливают дипломатические отношения.|Nguyen Hue defeats the Qing army; the two sides subsequently restore diplomatic relations.|Нгуен Хюэ Цин аскерин жеңет; кийин тараптар дипломатиялык мамилелерин калыбына келтирет.','Vietnam','war');

 // Learning notes are written for specific institutions, economies and communities.
 const edu=(id,y,g,e,s)=>{N(id,y,'government',g);N(id,y,'economy',e);N(id,y,'society',s);};
 edu('1789-qing',1759,'Гарнизоны и местные беки связывают новые области с императором.|Garrisons and local begs connect new territories to the emperor.|Гарнизондор жана жергиликтүү бектер жаңы аймактарды император менен байланыштырат.','Оазисное орошение, рынки и караваны обеспечивают жизнь Тарима.|Oasis irrigation, markets and caravans sustain the Tarim.|Оазис сугаты, базарлар жана кербендер Таримдин турмушун камсыздайт.','Маньчжурская, монгольская и местная администрации различаются.|Manchu, Mongol and local administrative arrangements differ.|Манжу, монгол жана жергиликтүү башкаруу тартиптери айырмаланат.');
 edu('late-kyrgyz-tianshan',1758,'Местные бии и родовые союзы сохраняют политическую роль.|Local biys and kin alliances retain political roles.|Жергиликтүү бийлер жана уруу союздары саясий ролун сактайт.','Сезонные пастбища связаны с оазисной торговлей.|Seasonal pastures connect with oasis trade.|Сезондук жайыттар оазис соодасы менен байланышат.','Китайское название «бурут» — название кыргызов в цинских документах.|Burut is a designation for the Kyrgyz in Qing documents.|«Бурут» — Цин документтериндеги кыргыздардын аталышы.');
 edu('1789-dzungar',1680,'Хан опирается на ойратскую знать и зависимые оазисные элиты.|The khan relies on Oirat nobles and dependent oasis elites.|Хан ойрот ак сөөктөрүнө жана көз каранды оазис төбөлдөрүнө таянат.','Скотоводство дополняют ремесло, торговля и оазисные доходы.|Pastoralism is supplemented by crafts, trade and oasis revenues.|Мал чарбасын кол өнөрчүлүк, соода жана оазис кирешелери толуктайт.','Буддийские монастыри участвуют в образовании и политических связях.|Buddhist monasteries participate in learning and political networks.|Будда монастырлары билимге жана саясий байланыштарга катышат.');
 edu('early-bukhara',1785,'Эмир соединяет военную власть с религиозным авторитетом.|The emir combines military power and religious authority.|Эмир аскердик бийликти диний кадыр-барк менен бириктирет.','Орошение и городские рынки поддерживают эмират.|Irrigation and urban markets sustain the emirate.|Сугат жана шаар базарлары эмирликти камсыздайт.','Улемы, торговцы, земледельцы и племенные элиты связаны с двором.|Scholars, traders, farmers and tribal elites connect with the court.|Уламалар, соодагерлер, дыйкандар жана уруу төбөлдөрү сарай менен байланышат.');
 edu('late-ottoman',1601,'Султан управляет через провинциальных наместников и местные элиты.|The sultan governs through provincial officials and local elites.|Султан провинция кызматкерлери жана жергиликтүү төбөлдөр аркылуу башкарат.','Рынки, ремесло и налоговые поступления связывают города и село.|Markets, crafts and tax revenues connect town and countryside.|Базарлар, кол өнөрчүлүк жана салыктар шаар менен айылды байланыштырат.','Религиозные общины, корпорации и домохозяйства образуют разные уровни общества.|Religious communities, corporations and households form different social levels.|Диний жамааттар, бирикмелер жана үй чарбалары коомдун ар түрдүү деңгээлдерин түзөт.');
 edu('early-safavid',1638,'Шах, военные служилые группы и улемы участвуют в управлении.|The shah, military service groups and scholars participate in government.|Шах, аскердик кызмат топтору жана уламалар башкарууга катышат.','Шёлк, ковры и караванные пути поддерживают городскую экономику.|Silk, carpets and caravan routes support the urban economy.|Жибек, килем жана кербен жолдору шаар чарбасын колдойт.','Исфахан объединяет придворные мастерские и разные торговые общины.|Isfahan brings together court workshops and diverse merchant communities.|Исфахан сарай устаканаларын жана ар түрдүү соодагер жамааттарын бириктирет.');
 edu('1789-oman',1650,'Имамы соединяют религиозный авторитет, племенные союзы и портовую власть.|Imams combine religious authority, tribal alliances and control of ports.|Имамдар диний кадыр-баркты, уруу союздарын жана порт бийлигин бириктирет.','Финики, морская торговля и судоходство дополняют друг друга.|Dates, maritime trade and shipping complement each other.|Курма, деңиз соодасы жана кеме каттамы бири-бирин толуктайт.','Оманские моряки связаны с многоязычными обществами Индийского океана.|Omani sailors connect with multilingual Indian Ocean societies.|Оман деңизчилери Инд океанынын көп тилдүү коомдору менен байланышат.');
 edu('1789-russian-empire',1721,'Императорская служба и губернское управление укрепляют центр.|Imperial service and provincial administration strengthen the centre.|Императордук кызмат жана губерниялык башкаруу борборду күчөтөт.','Металлургия, земледелие и балтийская торговля поддерживают военную державу.|Metallurgy, agriculture and Baltic trade support the military state.|Металлургия, дыйканчылык жана Балтика соодасы аскердик державаны колдойт.','Дворянские привилегии сосуществуют с крепостной зависимостью крестьян.|Noble privileges coexist with peasant serfdom.|Ак сөөк артыкчылыктары дыйкандардын крепостной көз карандылыгы менен катар жашайт.');
 edu('1789-siberian-river-centres',1661,'Остроги и воеводы создают сеть местного управления.|Forts and governors create a network of local administration.|Чептер жана воеводалар жергиликтүү башкаруу тармагын түзөт.','Пушнина, речной транспорт и ясак связывают далёкие районы.|Furs, river transport and tribute connect distant districts.|Баалуу тери, дарыя ташуусу жана ясак алыскы аймактарды байланыштырат.','Эвенкийские, якутские, бурятские и другие общества сохраняют местную жизнь.|Evenki, Sakha, Buryat and other societies retain local forms of life.|Эвенк, саха, бурят жана башка коомдор жергиликтүү турмушун сактайт.');
 edu('early-mughal',1601,'Мансабдары служат императору и получают права на доходы.|Mansabdars serve the emperor and receive assignments of revenue.|Мансабдарлар императорго кызмат кылып, кирешеден үлүш укугун алат.','Земельные доходы, ткани и межрегиональная торговля питают казну.|Land revenue, textiles and interregional trade support the treasury.|Жер кирешеси, кездеме жана аймак аралык соода казынаны камсыздайт.','Двор связывает разные языковые, религиозные и региональные элиты.|The court connects diverse linguistic, religious and regional elites.|Сарай ар түрдүү тилдик, диний жана аймактык төбөлдөрдү байланыштырат.');
 edu('1789-maratha',1720,'Пешва и военные дома разделяют власть с царской династией.|The peshwa and military houses share power with the royal dynasty.|Пешва жана аскердик үйлөр бийликти падышалык династия менен бөлүшөт.','Сборы чаут и земельные доходы обеспечивают армии.|Chauth levies and land revenues maintain armies.|Чаут жыйымдары жана жер кирешеси аскерлерди камсыздайт.','Маратхская власть действует через местных землевладельцев и союзников.|Maratha power works through local landholders and allies.|Маратха бийлиги жергиликтүү жер ээлери жана союздаштар аркылуу иштейт.');
 edu('1789-company-bengal',1765,'Торговая компания становится сборщиком государственных доходов.|A trading company becomes the collector of state revenues.|Соода компаниясы мамлекеттик кирешени чогултуучуга айланат.','Хлопчатобумажные ткани, шёлк и земельные сборы имеют решающее значение.|Cotton textiles, silk and land revenues are crucial.|Пахта кездеме, жибек жана жер салыгы чечүүчү мааниге ээ.','Местные работники и земледельцы продолжают жить при меняющемся режиме доходов.|Local workers and farmers live under a changing revenue regime.|Жергиликтүү жумушчулар жана дыйкандар өзгөргөн киреше тартибинде жашайт.');
 edu('japan',1635,'Сёгунат и владения даймё имеют разные уровни полномочий.|Shogunate and daimyo domains exercise different levels of authority.|Сёгунат жана даймё ээликтери бийликтин ар башка деңгээлин жүргүзөт.','Рисовые доходы, городские рынки и ремесло поддерживают рост.|Rice revenues, urban markets and crafts sustain growth.|Күрүч кирешеси, шаар базарлары жана кол өнөрчүлүк өсүштү колдойт.','Городская печать, театр и обучение расширяют круг читателей и зрителей.|Urban printing, theatre and schooling expand reading and viewing publics.|Шаар басмасы, театр жана билим окурман менен көрүүчүлөрдүн чөйрөсүн кеңейтет.');
 edu('late-ayutthaya',1601,'Царь управляет через служилую иерархию и местных правителей.|The king governs through a service hierarchy and local rulers.|Падыша кызмат иерархиясы жана жергиликтүү башкаруучулар аркылуу башкарат.','Рис, реки и международная торговля поддерживают столицу.|Rice, rivers and international trade sustain the capital.|Күрүч, дарыялар жана эл аралык соода борборду камсыздайт.','Буддийские монастыри и купеческие кварталы формируют городскую среду.|Buddhist monasteries and merchant quarters shape the city.|Будда монастырлары жана соодагер кварталдары шаар чөйрөсүн түзөт.');
 edu('early-java-sultanates',1755,'Разделённые династические дворы управляют при влиянии компании.|Divided dynastic courts govern under Company influence.|Бөлүнгөн династиялык сарайлар компаниянын таасиринде башкарат.','Рисоводство, ткани и обмен с побережьем поддерживают внутреннюю Яву.|Rice farming, textiles and coastal exchange sustain inland Java.|Күрүч өстүрүү, кездеме жана жээк соодасы ички Яваны камсыздайт.','Дворцовые ритуалы соединяют исламские и более ранние яванские традиции.|Court rituals combine Islamic and earlier Javanese traditions.|Сарай ырымдары исламдык жана мурдагы Ява салттарын бириктирет.');
 edu('1789-great-britain',1707,'Один парламент сочетается с сохранением шотландского права.|One Parliament coexists with retained Scots law.|Бир парламент шотланд укугунун сакталышы менен айкалышат.','Морская торговля, финансы и промышленность связывают разные районы.|Maritime trade, finance and industry connect different regions.|Деңиз соодасы, каржы жана өнөр жай ар түрдүү аймактарды байланыштырат.','Города растут; участие в политике остаётся социально ограниченным.|Cities grow; political participation remains socially restricted.|Шаарлар өсөт; саясатка катышуу социалдык жактан чектелген бойдон калат.');
 edu('late-hre',1648,'Император, князья и города делят полномочия в общей правовой системе.|Emperor, princes and cities share authority within a common legal framework.|Император, княздар жана шаарлар жалпы укуктук тутумда ыйгарым укуктарды бөлүшөт.','Региональные рынки и ремесло восстанавливаются после войны.|Regional markets and crafts recover after the war.|Аймактык базарлар жана кол өнөрчүлүк согуштан кийин калыбына келет.','Католические и протестантские земли сосуществуют в имперском порядке.|Catholic and Protestant territories coexist within the imperial order.|Католик жана протестант жерлери империялык тартипте катар жашайт.');
 edu('late-france',1789,'Национальное собрание оспаривает прежнюю сословную систему.|The National Assembly challenges the old estate system.|Улуттук жыйын мурдагы сословиелик тутумга каршы чыгат.','Финансовый кризис и продовольственные трудности усиливают политический конфликт.|Fiscal crisis and food shortages intensify political conflict.|Каржы кризиси жана азык-түлүк тартыштыгы саясий жаңжалды күчөтөт.','Городские и сельские движения участвуют в изменении общественного порядка.|Urban and rural movements participate in changing the social order.|Шаар жана айыл кыймылдары коомдук тартипти өзгөртүүгө катышат.');
